    if (site < node->site) {
        node->down_camp = unlink(std::move(node->down_camp), site, entry);
        return node;
    }
    if (node->site < site) {
        node->up_camp = unlink(std::move(node->up_camp), site, entry);
        return node;
    }
    if (node->down_camp && node->up_camp) {
        Node* successor = node->up_camp.get();
