    Node* current = pantry_.get();
    while (current) {
        if (jar == current->jar) break;
        current = jar < current->jar ? current->few.get() : current->many.get();
    }
    if (!current) return false;
    --total_jars_;
    if (current->bundles > 1) {
        --current->bundles;
        return true;
    }
    pantry_ = detach(std::move(pantry_), jar);
    --kinds_;
    return true;
}
