bool ParcelChuteMap::routed(std::int32_t chute) const {
    const Node* current = hub_.get();
    while (current) {
        if (chute == current->chute) return true;
        current = chute < current->chute ? current->slim_chute.get() : current->wide_chute.get();
    }
    return false;
}
