    std::string out = "~";
    for (const Cell& cell : cells_) {
        out += cell.occupied ? std::to_string(cell.frame) : ".";
        out += "~";
    }
    out += " flicker@" + std::to_string(oldest_) + " draw@" + std::to_string(next_);
    out += " used=" + std::to_string(used_) + "/" + std::to_string(cells_.size());
