constexpr double kPi = 3.14159265358979323846;
double normalize_azimuth(double angle) {
    double wrapped = std::fmod(angle, 2.0 * kPi);
    if (wrapped < 0.0) wrapped += 2.0 * kPi;
    return wrapped;
}
}
SurveyPoint::SurveyPoint(double dist, double azimuth) {
    double d = dist;
    double a = azimuth;
    if (d < 0.0) { d = -d; a += kPi; }
