    const std::string walked = rings();
    if (walked.empty()) return "";
    const std::size_t chunk = side();
    std::string result;
    for (std::size_t start = 0; start < walked.size(); start += chunk) {
        if (start != 0) result += '-';
        result += walked.substr(start, chunk);
    }
    return result;
}

}
