        const std::size_t nc = static_cast<std::size_t>(static_cast<long>(c) + dc[dir]);
        if (nr >= total_rows || nc >= cols || seen[nr][nc]) dir = (dir + 1) % 4;
        r = static_cast<std::size_t>(static_cast<long>(r) + dr[dir]);
