    int remaining = bees;
    for (int i = 0; i < hives; ++i) {
        const int load = remaining > capacity_ ? capacity_ : remaining;
        out.push_back(load);
        remaining -= load;
    }
    return out;
}
int HiveCensus::slack(int bees) const {
    return hives_needed(bees) * capacity_ - bees;
