bool operator==(const AaTreeGapCatalogResult& left, const AaTreeGapCatalogResult& right) { return left.answers == right.answers && left.mechanism_witness == right.mechanism_witness; }
std::optional<AaTreeGapCatalogResult> aa_tree_gap_catalog(const AaTreeGapCatalogRequest& request) {
  struct N{std::int64_t k;
  int level=1;
  std::unique_ptr<N>l,r;
  explicit N(std::int64_t x):k(x){}
  };
  std::unique_ptr<N>root;
  std::int64_t skewed=0,splitn=0;
  std::function<std::unique_ptr<N>(std::unique_ptr<N>)>skew=[&](std::unique_ptr<N>n){if(n&&n->l&&n->l->level==n->level){auto x=std::move(n->l);
  n->l=std::move(x->r);
  x->r=std::move(n);
  ++skewed;
  return x;
  }
  return n;
  };
  std::function<std::unique_ptr<N>(std::unique_ptr<N>)>split=[&](std::unique_ptr<N>n){if(n&&n->r&&n->r->r&&n->level==n->r->r->level){auto x=std::move(n->r);
  n->r=std::move(x->l);
  x->l=std::move(n);
  ++x->level;
  ++splitn;
  return x;
  }
  return n;
  };
  std::function<std::unique_ptr<N>(std::unique_ptr<N>,std::int64_t)>ins=[&](std::unique_ptr<N>n,std::int64_t x)->std::unique_ptr<N>{if(!n)return std::make_unique<N>(x);
  if(x==n->k)return {};
  if(x<n->k){auto z=ins(std::move(n->l),x);
  if(!z)return {};
  n->l=std::move(z);
  }else{auto z=ins(std::move(n->r),x);
  if(!z)return {};
  n->r=std::move(z);
  }
  return split(skew(std::move(n)));
  };
  for(auto x:request.initial_values){auto n=ins(std::move(root),x);
  if(!n)return std::nullopt;
  root=std::move(n);
  }
  std::vector<std::int64_t>ans;
  for(const auto&o:request.operations){if(o.opcode!=0)return std::nullopt;
  N*n=root.get();
  std::optional<std::int64_t>p,s;
  while(n){if(n->k<o.first){p=n->k;
  n=n->r.get();
  }else{s=n->k;
  n=n->l.get();
  }
  }
  ans.push_back(p?o.first-*p:-1);
  ans.push_back(s?*s-o.first:-1);
  }
  return AaTreeGapCatalogResult{ans,{skewed,splitn}
  };

}
}
