std::optional<BinaryTriePredecessorXorResult> binary_trie_predecessor_xor(const BinaryTriePredecessorXorRequest& request) {
  if(request.parameter<=0||request.parameter>62)return std::nullopt;
  struct N{int c[2]={-1,-1};
  int n=0;
  };
  std::vector<N>t(1);
  auto add=[&](std::int64_t x){if(x<0||x>=(1LL<<request.parameter))return false;
  int p=0;
  ++t[0].n;
  for(int b=static_cast<int>(request.parameter)-1;b>=0;--b){int q=static_cast<int>((x>>b)&1);
  if(t[p].c[q]<0){t[p].c[q]=static_cast<int>(t.size());
  t.push_back(N{});
  }
  p=t[p].c[q];
  ++t[p].n;
  }
  return true;
  };
  for(auto x:request.initial_values)if(!add(x))return std::nullopt;
  std::vector<std::int64_t>ans;
  std::int64_t steps=0;
  for(const auto&o:request.operations){if(o.opcode!=0||o.first<0)return std::nullopt;
  int p=0;
  std::int64_t x=0;
  for(int b=static_cast<int>(request.parameter)-1;b>=0;--b){int want=1-static_cast<int>((o.first>>b)&1);
  if(t[p].c[want]>=0&&t[static_cast<std::size_t>(t[p].c[want])].n>0){x|=static_cast<std::int64_t>(want)<<b;
  p=t[p].c[want];
  }else p=t[p].c[1-want];
  ++steps;
  }
  ans.push_back(x);
  }
  return BinaryTriePredecessorXorResult{ans,{steps,static_cast<std::int64_t>(t.size())}
  };

}
