bool operator==(const BplusLeafRangeScanResult& left, const BplusLeafRangeScanResult& right) { return left.answers == right.answers && left.mechanism_witness == right.mechanism_witness; }
std::optional<BplusLeafRangeScanResult> bplus_leaf_range_scan(const BplusLeafRangeScanRequest& request) {
  struct R{std::int64_t k,id;
  };
  struct N{bool leaf=false;
  std::vector<std::int64_t>sep;
  std::vector<N*>child;
  std::vector<R>rec;
  N*next=nullptr;
  };
  std::vector<std::unique_ptr<N>>pool;
  auto make=[&](){pool.push_back(std::make_unique<N>());
  return pool.back().get();
  };
  std::vector<R>all;
  if(request.initial_values.size()%2)return std::nullopt;
  for(std::size_t i=0;i<request.initial_values.size();i+=2)all.push_back({request.initial_values[i],request.initial_values[i+1]});
  std::sort(all.begin(),all.end(),[](R a,R b){return std::tie(a.k,a.id)<std::tie(b.k,b.id);});
  std::vector<N*>level;
  N*previous=nullptr;
  for(std::size_t i=0;i<all.size();i+=3){N*n=make();
  n->leaf=true;
  n->rec.assign(all.begin()+i,all.begin()+std::min(all.size(),i+3));
  if(previous)previous->next=n;
  previous=n;
  level.push_back(n);
  }
  auto minimum=[](N*n){while(!n->leaf)n=n->child.front();
  return n->rec.front().k;
  };
  while(level.size()>1){std::vector<N*>up;
  for(std::size_t i=0;i<level.size();i+=3){N*n=make();
  for(std::size_t j=i;j<std::min(level.size(),i+3);++j)n->child.push_back(level[j]);
  for(std::size_t j=1;j<n->child.size();++j)n->sep.push_back(minimum(n->child[j]));
  up.push_back(n);
  }
  level=std::move(up);
  }
  N*root=level.empty()?nullptr:level[0];
  std::vector<std::int64_t>ans;
  for(const auto&o:request.operations){if(o.opcode!=0||o.first>o.second)return std::nullopt;
  N*n=root;
  if(!n)continue;
  while(!n->leaf)n=n->child[std::upper_bound(n->sep.begin(),n->sep.end(),o.first)-n->sep.begin()];
  for(;n;n=n->next){bool stop=false;
  for(auto r:n->rec){if(r.k>o.second){stop=true;
  break;
  }
  if(r.k>=o.first){ans.push_back(r.k);
  ans.push_back(r.id);
  }
  }
  if(stop)break;
  }
  }
  return BplusLeafRangeScanResult{ans,{static_cast<std::int64_t>(pool.size()),static_cast<std::int64_t>(all.size())}
  };

}
}
