bool operator==(const BtreePageSuccessorIndexResult& left, const BtreePageSuccessorIndexResult& right) { return left.answers == right.answers && left.mechanism_witness == right.mechanism_witness; }
std::optional<BtreePageSuccessorIndexResult> btree_page_successor_index(const BtreePageSuccessorIndexRequest& request) {
  constexpr std::size_t degree=3;
  struct N{bool leaf=true;
  std::vector<std::int64_t>k;
  std::vector<std::unique_ptr<N>>c;
  };
  auto root=std::make_unique<N>();
  std::int64_t splits=0;
  auto split=[&](N*p,std::size_t i){N*y=p->c[i].get();
  auto z=std::make_unique<N>();
  z->leaf=y->leaf;
  auto middle=y->k[degree-1];
  z->k.assign(y->k.begin()+degree,y->k.end());
  y->k.resize(degree-1);
  if(!y->leaf){for(std::size_t j=degree;j<y->c.size();++j)z->c.push_back(std::move(y->c[j]));
  y->c.resize(degree);
  }
  p->k.insert(p->k.begin()+i,middle);
  p->c.insert(p->c.begin()+i+1,std::move(z));
  ++splits;
  };
  std::function<bool(N*,std::int64_t)>insert=[&](N*n,std::int64_t x){auto it=std::lower_bound(n->k.begin(),n->k.end(),x);
  if(it!=n->k.end()&&*it==x)return false;
  if(n->leaf){n->k.insert(it,x);
  return true;
  }
  std::size_t i=it-n->k.begin();
  if(n->c[i]->k.size()==2*degree-1){split(n,i);
  if(x==n->k[i])return false;
  if(x>n->k[i])++i;
  }
  return insert(n->c[i].get(),x);
  };
  for(auto x:request.initial_values){if(root->k.size()==2*degree-1){auto p=std::make_unique<N>();
  p->leaf=false;
  p->c.push_back(std::move(root));
  split(p.get(),0);
  root=std::move(p);
  }
  if(!insert(root.get(),x))return std::nullopt;
  }
  std::vector<std::int64_t>ans;
  for(const auto&o:request.operations){if(o.opcode!=0)return std::nullopt;
  N*n=root.get();
  std::optional<std::int64_t>best;
  while(n){auto it=std::upper_bound(n->k.begin(),n->k.end(),o.first);
  if(it!=n->k.end())best=*it;
  if(n->leaf)break;
  n=n->c[it-n->k.begin()].get();
  }
  ans.push_back(best?*best:std::numeric_limits<std::int64_t>::max());
  }
  return BtreePageSuccessorIndexResult{ans,{splits,static_cast<std::int64_t>(root->k.size())}
  };

}
}
