bool operator==(const CartesianRmqAncestorIndexResult& left, const CartesianRmqAncestorIndexResult& right) { return left.answers == right.answers && left.mechanism_witness == right.mechanism_witness; }
std::optional<CartesianRmqAncestorIndexResult> cartesian_rmq_ancestor_index(const CartesianRmqAncestorIndexRequest& request) {
  if(request.initial_values.empty())return std::nullopt;
  int n=request.initial_values.size();
  std::vector<int>left(n,-1),right(n,-1),parent(n,-1),stack;
  std::int64_t pops=0;
  for(int i=0;i<n;++i){int last=-1;
  while(!stack.empty()&&request.initial_values[i]<request.initial_values[stack.back()]){last=stack.back();
  stack.pop_back();
  ++pops;
  }
  if(!stack.empty()){right[stack.back()]=i;
  parent[i]=stack.back();
  }
  if(last>=0){left[i]=last;
  parent[last]=i;
  }
  stack.push_back(i);
  }
  int root=0;
  while(parent[root]>=0)root=parent[root];
  std::vector<int>euler,depth,first(n,-1);
  std::function<void(int,int)>dfs=[&](int v,int d){if(v<0)return;
  if(first[v]<0)first[v]=euler.size();
  euler.push_back(v);
  depth.push_back(d);
  if(left[v]>=0){dfs(left[v],d+1);
  euler.push_back(v);
  depth.push_back(d);
  }
  if(right[v]>=0){dfs(right[v],d+1);
  euler.push_back(v);
  depth.push_back(d);
  }
  };
  dfs(root,0);
  std::vector<std::vector<int>>st{std::vector<int>(euler.size())};
  std::iota(st[0].begin(),st[0].end(),0);
  for(std::size_t k=1;(1ULL<<k)<=euler.size();++k){std::size_t len=1ULL<<k;
  std::vector<int>row(euler.size()-len+1);
  for(std::size_t i=0;i<row.size();++i){int a=st[k-1][i],b=st[k-1][i+len/2];
  row[i]=depth[a]<=depth[b]?a:b;
  }
  st.push_back(std::move(row));
  }
  std::vector<std::int64_t>ans;
  for(const auto&o:request.operations){if(o.opcode!=0||o.first<0||o.second<o.first||o.second>=n)return std::nullopt;
  int l=first[o.first],r=first[o.second];
  if(l>r)std::swap(l,r);
  int len=r-l+1,k=0;
  while((2<<k)<=len)++k;
  int a=st[k][l],b=st[k][r-(1<<k)+1];
  ans.push_back(euler[depth[a]<=depth[b]?a:b]);
  }
  return CartesianRmqAncestorIndexResult{ans,{pops,static_cast<std::int64_t>(euler.size())}
  };

}
}
