bool operator==(const DisjointSparseTableFoldResult& left, const DisjointSparseTableFoldResult& right) { return left.answers == right.answers && left.mechanism_witness == right.mechanism_witness; }
std::optional<DisjointSparseTableFoldResult> disjoint_sparse_table_fold(const DisjointSparseTableFoldRequest& request) {
  if(request.parameter<2||request.initial_values.empty())return std::nullopt;
  for(auto x:request.initial_values)if(x<0||x>9)return std::nullopt;
  using P=std::pair<std::int64_t,int>;
  auto combine=[&](P x,P y){std::int64_t p=1;
  for(int i=0;i<y.second;++i)p=p*10%request.parameter;
  return P{(x.first*p+y.first)%request.parameter,x.second+y.second};
  };
  std::size_t n=request.initial_values.size();
  int levels=1;
  while((1ULL<<levels)<n)++levels;
  std::vector<std::vector<P>>tab(levels,std::vector<P>(n));
  for(int k=0;k<levels;++k){std::size_t block=1ULL<<(k+1);
  for(std::size_t base=0;base<n;base+=block){auto mid=std::min(n,base+block/2),end=std::min(n,base+block);
  if(mid>base){tab[k][mid-1]={request.initial_values[mid-1],1};
  for(std::size_t i=mid-1;i-->base;)tab[k][i]=combine({request.initial_values[i],1},tab[k][i+1]);
  }
  if(mid<end){tab[k][mid]={request.initial_values[mid],1};
  for(std::size_t i=mid+1;i<end;++i)tab[k][i]=combine(tab[k][i-1],{request.initial_values[i],1});
  }
  }
  }
  std::vector<std::int64_t>ans;
  for(const auto&o:request.operations){if(o.opcode!=0||o.first<0||o.second<=o.first||static_cast<std::size_t>(o.second)>n)return std::nullopt;
  std::size_t l=o.first,r=o.second-1;
  if(l==r)ans.push_back(request.initial_values[l]%request.parameter);
  else{int k=0;
  for(auto x=l^r;x>>=1;)++k;
  ans.push_back(combine(tab[k][l],tab[k][r]).first);
  }
  }
  return DisjointSparseTableFoldResult{ans,{levels,static_cast<std::int64_t>(tab.size())}
  };

}
