std::optional<FenwickRangeDeltaLedgerResult> fenwick_range_delta_ledger(const FenwickRangeDeltaLedgerRequest& request) {
  if(request.initial_values.empty())return std::nullopt;
  std::size_t n=request.initial_values.size();
  std::vector<std::int64_t>a(n+2),b(n+2);
  auto add=[&](std::vector<std::int64_t>&bit,std::size_t i,std::int64_t d){for(++i;i<bit.size();i+=i&(~i+1))bit[i]+=d;
  };
  auto range=[&](std::size_t l,std::size_t r,std::int64_t d){add(a,l,d);
  add(a,r+1,-d);
  add(b,l,d*static_cast<std::int64_t>(l));
  add(b,r+1,-d*static_cast<std::int64_t>(r+1));
  };
  for(std::size_t i=0;i<n;++i)range(i,i,request.initial_values[i]);
  auto prefix=[&](std::size_t count){std::int64_t x=0,y=0;
  for(std::size_t i=count;i;i-=i&(~i+1)){x+=a[i];
  y+=b[i];
  }
  return x*static_cast<std::int64_t>(count)-y;
  };
  std::vector<std::int64_t>ans;
  std::int64_t changes=0;
  for(const auto&o:request.operations){if(o.first<0||o.second<o.first||static_cast<std::size_t>(o.second)>=n)return std::nullopt;
  std::size_t l=o.first,r=o.second;
  if(o.opcode==1){range(l,r,o.third);
  changes+=4;
  }else if(o.opcode==0)ans.push_back(prefix(r+1)-prefix(l));
  else return std::nullopt;
  }
  return FenwickRangeDeltaLedgerResult{ans,{changes,static_cast<std::int64_t>(a.size())}
  };

}
}
