  if(request.initial_values.empty())return std::nullopt;
  std::size_t n=request.initial_values.size();
  std::vector<std::int64_t>b(n+1);
  auto add=[&](std::size_t i,std::int64_t d){for(++i;i<=n;i+=i&(~i+1))b[i]+=d;
  };
  for(std::size_t i=0;i<n;++i){if(request.initial_values[i]<0)return std::nullopt;
  add(i,request.initial_values[i]);
  }
  std::vector<std::int64_t>ans;
  std::int64_t jumps=0;
  for(const auto&o:request.operations){if(o.opcode!=0||o.first<=0)return std::nullopt;
  std::size_t idx=0,step=1;
  while(step*2<=n)step*=2;
  std::int64_t need=o.first;
  for(;step;step/=2){std::size_t next=idx+step;
  if(next<=n&&b[next]<need){idx=next;
  need-=b[next];
  ++jumps;
  }
  }
  if(idx==n)return std::nullopt;
  ans.push_back(static_cast<std::int64_t>(idx+1));
  }
  return FenwickRankLocatorResult{ans,{jumps}
  };

