std::optional<FenwickTwoDimensionalRectanglesResult> fenwick_two_dimensional_rectangles(const FenwickTwoDimensionalRectanglesRequest& request) {
  if(request.initial_values.empty()||request.initial_values.size()%3)return std::nullopt;
  std::int64_t side=0;
  for(std::size_t i=0;i<request.initial_values.size();i+=3){if(request.initial_values[i]<0||request.initial_values[i+1]<0)return std::nullopt;
  side=std::max({side,request.initial_values[i]+1,request.initial_values[i+1]+1});
  }
  std::size_t n=side;
  std::vector<std::vector<std::int64_t>>bit(n+1,std::vector<std::int64_t>(n+1));
  std::int64_t hops=0;
  auto add=[&](std::size_t r,std::size_t c,std::int64_t v){for(++r;r<=n;r+=r&(~r+1))for(std::size_t j=c+1;j<=n;j+=j&(~j+1)){bit[r][j]+=v;
  ++hops;
  }
  };
  for(std::size_t i=0;i<request.initial_values.size();i+=3)add(request.initial_values[i],request.initial_values[i+1],request.initial_values[i+2]);
  auto sum=[&](std::int64_t r,std::int64_t c){if(r<0||c<0)return std::int64_t{0};
  std::int64_t s=0;
  for(std::size_t i=r+1;i;i-=i&(~i+1))for(std::size_t j=c+1;j;j-=j&(~j+1))s+=bit[i][j];
  return s;
  };
  std::vector<std::int64_t>ans;
  for(const auto&o:request.operations){if(o.opcode!=0||o.first<0||o.second<o.first||o.third<0||request.parameter<o.third||o.second>=side||request.parameter>=side)return std::nullopt;
  ans.push_back(sum(o.second,request.parameter)-sum(o.first-1,request.parameter)-sum(o.second,o.third-1)+sum(o.first-1,o.third-1));
  }
  return FenwickTwoDimensionalRectanglesResult{ans,{hops}
  };

}
}
