bool operator==(const FractionalCascadeBandSearchResult& left, const FractionalCascadeBandSearchResult& right) { return left.answers == right.answers && left.mechanism_witness == right.mechanism_witness; }
std::optional<FractionalCascadeBandSearchResult> fractional_cascade_band_search(const FractionalCascadeBandSearchRequest& request) {
  std::vector<std::vector<std::int64_t>>cat;
  std::vector<std::int64_t>current;
  for(auto x:request.initial_values){if(x==std::numeric_limits<std::int64_t>::min()){if(current.empty()||!std::is_sorted(current.begin(),current.end()))return std::nullopt;
  cat.push_back(current);
  current.clear();
  }else current.push_back(x);
  }
  if(!current.empty()){if(!std::is_sorted(current.begin(),current.end()))return std::nullopt;
  cat.push_back(current);
  }
  if(cat.empty())return std::nullopt;
  std::size_t n=cat.size();
  std::vector<std::vector<std::int64_t>>aug(n);
  aug.back()=cat.back();
  for(std::size_t i=n-1;i-->0;){aug[i]=cat[i];
  for(std::size_t j=1;j<aug[i+1].size();j+=2)aug[i].push_back(aug[i+1][j]);
  std::sort(aug[i].begin(),aug[i].end());
  aug[i].erase(std::unique(aug[i].begin(),aug[i].end()),aug[i].end());
  }
  std::vector<std::vector<std::size_t>>to_original(n),down(n);
  for(std::size_t i=0;i<n;++i){for(auto x:aug[i]){to_original[i].push_back(std::lower_bound(cat[i].begin(),cat[i].end(),x)-cat[i].begin());
  if(i+1<n)down[i].push_back(std::lower_bound(aug[i+1].begin(),aug[i+1].end(),x)-aug[i+1].begin());
  }
  }
  std::vector<std::int64_t>ans;
  std::int64_t corrections=0;
  for(const auto&o:request.operations){if(o.opcode!=0)return std::nullopt;
  std::size_t pos=std::lower_bound(aug[0].begin(),aug[0].end(),o.first)-aug[0].begin();
  for(std::size_t i=0;i<n;++i){std::size_t original=pos<aug[i].size()?to_original[i][pos]:cat[i].size();
  while(original>0&&cat[i][original-1]>=o.first){--original;
  ++corrections;
  }
  while(original<cat[i].size()&&cat[i][original]<o.first){++original;
  ++corrections;
  }
  ans.push_back(original==cat[i].size()?std::numeric_limits<std::int64_t>::max():cat[i][original]);
  if(i+1<n){std::size_t candidate=pos<down[i].size()?down[i][pos]:aug[i+1].size();
  if(pos>0)candidate=std::min(candidate,down[i][pos-1]);
  pos=candidate;
  while(pos<aug[i+1].size()&&aug[i+1][pos]<o.first){++pos;
  ++corrections;
  }
  }
  }
  }
  return FractionalCascadeBandSearchResult{ans,{corrections,static_cast<std::int64_t>(cat.size())}
  };

}
}
