bool operator==(const ImplicitTreapReversalRankResult& left, const ImplicitTreapReversalRankResult& right) { return left.answers == right.answers && left.mechanism_witness == right.mechanism_witness; }
std::optional<ImplicitTreapReversalRankResult> implicit_treap_reversal_rank(const ImplicitTreapReversalRankRequest& request) {
  struct N{std::int64_t v;
  std::uint64_t p;
  int s=1;
  bool rev=false;
  std::unique_ptr<N>l,r;
  N(std::int64_t x,std::uint64_t q):v(x),p(q){}
  };
  auto size=[](const std::unique_ptr<N>&n){return n?n->s:0;
  };
  auto pull=[&](N*n){n->s=1+size(n->l)+size(n->r);
  };
  std::function<void(N*)>push=[&](N*n){if(n&&n->rev){std::swap(n->l,n->r);
  if(n->l)n->l->rev=!n->l->rev;
  if(n->r)n->r->rev=!n->r->rev;
  n->rev=false;
  }
  };
  std::function<void(std::unique_ptr<N>,int,std::unique_ptr<N>&,std::unique_ptr<N>&)>split=[&](std::unique_ptr<N>n,int k,std::unique_ptr<N>&a,std::unique_ptr<N>&b){if(!n){a.reset();
  b.reset();
  return;
  }
  push(n.get());
  if(size(n->l)>=k){split(std::move(n->l),k,a,n->l);
  pull(n.get());
  b=std::move(n);
  }else{split(std::move(n->r),k-size(n->l)-1,n->r,b);
  pull(n.get());
  a=std::move(n);
  }
  };
  std::function<std::unique_ptr<N>(std::unique_ptr<N>,std::unique_ptr<N>)>merge=[&](std::unique_ptr<N>a,std::unique_ptr<N>b)->std::unique_ptr<N>{if(!a)return b;
  if(!b)return a;
  if(a->p>b->p){push(a.get());
  a->r=merge(std::move(a->r),std::move(b));
  pull(a.get());
  return a;
  }
  push(b.get());
  b->l=merge(std::move(a),std::move(b->l));
  pull(b.get());
  return b;
  };
  std::unique_ptr<N>root;
  std::uint64_t seed=7;
  for(auto x:request.initial_values){seed=seed*6364136223846793005ULL+1;
  root=merge(std::move(root),std::make_unique<N>(x,seed));
  }
  std::vector<std::int64_t>ans;
  std::int64_t toggles=0;
  for(const auto&o:request.operations){if(o.opcode==1){if(o.first<0||o.second<=o.first||o.second>size(root))return std::nullopt;
  std::unique_ptr<N>a,b,c;
  split(std::move(root),o.first,a,b);
  split(std::move(b),o.second-o.first,b,c);
  b->rev=!b->rev;
  ++toggles;
  root=merge(merge(std::move(a),std::move(b)),std::move(c));
  }else if(o.opcode==0){if(o.first<0||o.first>=size(root))return std::nullopt;
  N*n=root.get();
  int k=o.first;
  while(n){push(n);
  if(k<size(n->l))n=n->l.get();
  else if(k==size(n->l)){ans.push_back(n->v);
  break;
  }else{k-=size(n->l)+1;
  n=n->r.get();
  }
  }
  }else return std::nullopt;
  }
  return ImplicitTreapReversalRankResult{ans,{toggles,size(root),root?root->s:0}
  };

}
}
