bool operator==(const IntervalTreeOverlapRankResult& left, const IntervalTreeOverlapRankResult& right) { return left.answers == right.answers && left.mechanism_witness == right.mechanism_witness; }
std::optional<IntervalTreeOverlapRankResult> interval_tree_overlap_rank(const IntervalTreeOverlapRankRequest& request) {
  if(request.initial_values.size()%3)return std::nullopt;
  struct I{std::int64_t a,b,id,mx;
  std::unique_ptr<I>l,r;
  I(std::int64_t x,std::int64_t y,std::int64_t z):a(x),b(y),id(z),mx(y){}
  };
  std::unique_ptr<I>root;
  std::int64_t pruned=0,nodes=0;
  std::function<bool(std::unique_ptr<I>&,std::int64_t,std::int64_t,std::int64_t)>add=[&](std::unique_ptr<I>&n,std::int64_t a,std::int64_t b,std::int64_t id){if(a>b)return false;
  if(!n){n=std::make_unique<I>(a,b,id);
  ++nodes;
  return true;
  }
  if(std::tie(a,id)==std::tie(n->a,n->id))return false;
  bool ok=std::tie(a,id)<std::tie(n->a,n->id)?add(n->l,a,b,id):add(n->r,a,b,id);
  n->mx=std::max({n->b,n->l?n->l->mx:std::numeric_limits<std::int64_t>::min(),n->r?n->r->mx:std::numeric_limits<std::int64_t>::min()});
  return ok;
  };
  for(std::size_t i=0;i+2<request.initial_values.size();i+=3)if(!add(root,request.initial_values[i],request.initial_values[i+1],request.initial_values[i+2]))return std::nullopt;
  std::vector<std::int64_t>ans;
  for(const auto&o:request.operations){if(o.opcode!=0||o.first>o.second)return std::nullopt;
  std::function<int(const I*)>count=[&](const I*n){if(!n)return 0;
  int v=(n->a<=o.second&&n->b>=o.first)?1:0;
  if(n->l&&n->l->mx>=o.first)v+=count(n->l.get());
  else if(n->l)++pruned;
  if(n->a<=o.second)v+=count(n->r.get());
  return v;
  };
  ans.push_back(count(root.get()));
  }
  return IntervalTreeOverlapRankResult{ans,{pruned,nodes}
  };

}
}
