bool operator==(const IntervalUnionCoveredRankResult& left, const IntervalUnionCoveredRankResult& right) { return left.answers == right.answers && left.mechanism_witness == right.mechanism_witness; }
std::optional<IntervalUnionCoveredRankResult> interval_union_covered_rank(const IntervalUnionCoveredRankRequest& request) {
  if(request.initial_values.size()%2)return std::nullopt;
  std::vector<std::pair<std::int64_t,std::int64_t>>spans;
  std::int64_t merges=0;
  auto cover=[&](std::int64_t a,std::int64_t b){if(a>b)return false;
  spans.push_back({a,b});
  std::sort(spans.begin(),spans.end());
  std::vector<std::pair<std::int64_t,std::int64_t>>m;
  for(auto s:spans){if(m.empty()||s.first>m.back().second+1)m.push_back(s);
  else{m.back().second=std::max(m.back().second,s.second);
  ++merges;
  }
  }
  spans=std::move(m);
  return true;
  };
  for(std::size_t i=0;i+1<request.initial_values.size();i+=2)if(!cover(request.initial_values[i],request.initial_values[i+1]))return std::nullopt;
  std::vector<std::int64_t>ans;
  for(const auto&o:request.operations){if(o.opcode==1){if(!cover(o.first,o.second))return std::nullopt;
  }else if(o.opcode==0){if(o.first<0)return std::nullopt;
  std::int64_t k=o.first;
  bool found=false;
  for(auto s:spans){auto len=s.second-s.first+1;
  if(k<len){ans.push_back(s.first+k);
  found=true;
  break;
  }
  k-=len;
  }
  if(!found)return std::nullopt;
  }else return std::nullopt;
  }
  return IntervalUnionCoveredRankResult{ans,{merges,static_cast<std::int64_t>(spans.size())}
  };

}
}
