bool operator==(const KdTreeRectangleReportResult& left, const KdTreeRectangleReportResult& right) { return left.answers == right.answers && left.mechanism_witness == right.mechanism_witness; }
std::optional<KdTreeRectangleReportResult> kd_tree_rectangle_report(const KdTreeRectangleReportRequest& request) {
  if(request.initial_values.empty()||request.initial_values.size()%3)return std::nullopt;
  struct P{std::int64_t x,y,id;
  };
  std::vector<P>p;
  std::set<std::int64_t>ids;
  for(std::size_t i=0;i<request.initial_values.size();i+=3){if(!ids.insert(request.initial_values[i+2]).second)return std::nullopt;
  p.push_back({request.initial_values[i],request.initial_values[i+1],request.initial_values[i+2]});
  }
  struct N{P p;
  std::int64_t x1,x2,y1,y2;
  std::unique_ptr<N>a,b;
  };
  std::function<std::unique_ptr<N>(int,int,int)>build=[&](int l,int r,int d){if(l>=r)return std::unique_ptr<N>{};
  int m=(l+r)/2;
  std::nth_element(p.begin()+l,p.begin()+m,p.begin()+r,[&](P x,P y){return d%2?std::tie(x.y,x.x,x.id)<std::tie(y.y,y.x,y.id):std::tie(x.x,x.y,x.id)<std::tie(y.x,y.y,y.id);});
  auto n=std::make_unique<N>();
  n->p=p[m];
  n->a=build(l,m,d+1);
  n->b=build(m+1,r,d+1);
  n->x1=n->x2=n->p.x;
  n->y1=n->y2=n->p.y;
  for(N*c:{n->a.get(),n->b.get()})if(c){n->x1=std::min(n->x1,c->x1);
  n->x2=std::max(n->x2,c->x2);
  n->y1=std::min(n->y1,c->y1);
  n->y2=std::max(n->y2,c->y2);
  }
  return n;
  };
  auto root=build(0,p.size(),0);
  std::int64_t boxes=0;
  std::function<void(const N*,std::int64_t,std::int64_t,std::int64_t,std::int64_t,std::vector<std::int64_t>&)>report=[&](const N*n,std::int64_t x1,std::int64_t x2,std::int64_t y1,std::int64_t y2,std::vector<std::int64_t>&out){if(!n)return;
  ++boxes;
  if(n->x2<x1||n->x1>x2||n->y2<y1||n->y1>y2)return;
  if(n->p.x>=x1&&n->p.x<=x2&&n->p.y>=y1&&n->p.y<=y2)out.push_back(n->p.id);
  report(n->a.get(),x1,x2,y1,y2,out);
  report(n->b.get(),x1,x2,y1,y2,out);
  };
  std::vector<std::int64_t>ans;
  for(const auto&o:request.operations){if(o.opcode!=0||o.first>o.second||o.third>request.parameter)return std::nullopt;
  std::vector<std::int64_t>hit;
  report(root.get(),o.first,o.second,o.third,request.parameter,hit);
  std::sort(hit.begin(),hit.end());
  ans.insert(ans.end(),hit.begin(),hit.end());
  ans.push_back(-1);
  }
  return KdTreeRectangleReportResult{ans,{boxes,static_cast<std::int64_t>(ids.size())}
  };

}
}
