bool operator==(const LazySegmentAffineSumResult& left, const LazySegmentAffineSumResult& right) { return left.answers == right.answers && left.mechanism_witness == right.mechanism_witness; }
std::optional<LazySegmentAffineSumResult> lazy_segment_affine_sum(const LazySegmentAffineSumRequest& request) {
  if(request.initial_values.empty())return std::nullopt;
  std::size_t n=request.initial_values.size();
  std::vector<std::int64_t>s(4*n),lm(4*n,1),la(4*n);
  std::int64_t pushes=0;
  std::function<void(std::size_t,std::size_t,std::size_t)>build=[&](std::size_t p,std::size_t l,std::size_t r){if(r-l==1){s[p]=request.initial_values[l];
  return;
  }
  auto m=(l+r)/2;
  build(2*p,l,m);
  build(2*p+1,m,r);
  s[p]=s[2*p]+s[2*p+1];
  };
  build(1,0,n);
  auto apply=[&](std::size_t p,std::size_t len,std::int64_t m,std::int64_t a){s[p]=s[p]*m+static_cast<std::int64_t>(len)*a;
  lm[p]*=m;
  la[p]=la[p]*m+a;
  };
  std::function<void(std::size_t,std::size_t,std::size_t)>push=[&](std::size_t p,std::size_t l,std::size_t r){if(r-l==1||(lm[p]==1&&la[p]==0))return;
  auto m=(l+r)/2;
  apply(2*p,m-l,lm[p],la[p]);
  apply(2*p+1,r-m,lm[p],la[p]);
  lm[p]=1;
  la[p]=0;
  ++pushes;
  };
  std::function<void(std::size_t,std::size_t,std::size_t,std::size_t,std::size_t,std::int64_t,std::int64_t)>update=[&](std::size_t p,std::size_t l,std::size_t r,std::size_t ql,std::size_t qr,std::int64_t m,std::int64_t a){if(qr<=l||r<=ql)return;
  if(ql<=l&&r<=qr){apply(p,r-l,m,a);
  return;
  }
  push(p,l,r);
  auto mid=(l+r)/2;
  update(2*p,l,mid,ql,qr,m,a);
  update(2*p+1,mid,r,ql,qr,m,a);
  s[p]=s[2*p]+s[2*p+1];
  };
  std::function<std::int64_t(std::size_t,std::size_t,std::size_t,std::size_t,std::size_t)>query=[&](std::size_t p,std::size_t l,std::size_t r,std::size_t ql,std::size_t qr){if(qr<=l||r<=ql)return std::int64_t{0};
  if(ql<=l&&r<=qr)return s[p];
  push(p,l,r);
  auto m=(l+r)/2;
  return query(2*p,l,m,ql,qr)+query(2*p+1,m,r,ql,qr);
  };
  std::vector<std::int64_t>ans;
  for(const auto&o:request.operations){if(o.first<0||o.second<o.first||static_cast<std::size_t>(o.second)>=n)return std::nullopt;
  if(o.opcode==1)update(1,0,n,o.first,o.second+1,o.third,request.parameter);
  else if(o.opcode==0)ans.push_back(query(1,0,n,o.first,o.second+1));
  else return std::nullopt;
  }
  return LazySegmentAffineSumResult{ans,{pushes,static_cast<std::int64_t>(s.size())}
  };

}
}
