std::optional<MergeSortTreeThresholdCountResult> merge_sort_tree_threshold_count(const MergeSortTreeThresholdCountRequest& request) {
  if(request.initial_values.empty())return std::nullopt;
  std::size_t n=1;
  while(n<request.initial_values.size())n*=2;
  std::vector<std::vector<std::int64_t>>t(2*n);
  for(std::size_t i=0;i<request.initial_values.size();++i)t[n+i]={request.initial_values[i]};
  for(std::size_t i=n;i-->1;){std::merge(t[2*i].begin(),t[2*i].end(),t[2*i+1].begin(),t[2*i+1].end(),std::back_inserter(t[i]));
  }
  std::vector<std::int64_t>ans;
  std::int64_t catalogs=0;
  for(const auto&o:request.operations){if(o.opcode!=0||o.first<0||o.second<=o.first||static_cast<std::size_t>(o.second)>request.initial_values.size())return std::nullopt;
  std::size_t l=n+static_cast<std::size_t>(o.first),r=n+static_cast<std::size_t>(o.second);
  std::int64_t c=0;
  while(l<r){if(l&1U){c+=std::upper_bound(t[l].begin(),t[l].end(),o.third)-t[l].begin();
  ++l;
  ++catalogs;
  }
  if(r&1U){--r;
  c+=std::upper_bound(t[r].begin(),t[r].end(),o.third)-t[r].begin();
  ++catalogs;
  }
  l/=2;
  r/=2;
  }
  ans.push_back(c);
  }
  return MergeSortTreeThresholdCountResult{ans,{catalogs}
  };

}
