std::optional<MoDistinctRangeReplayResult> mo_distinct_range_replay(const MoDistinctRangeReplayRequest& request) {
  if(request.initial_values.empty())return std::nullopt;
  struct Q{int l,r,i;
  };
  std::vector<Q>qs;
  for(std::size_t i=0;i<request.operations.size();++i){const auto&o=request.operations[i];
  if(o.opcode!=0||o.first<0||o.second<=o.first||static_cast<std::size_t>(o.second)>request.initial_values.size())return std::nullopt;
  qs.push_back({static_cast<int>(o.first),static_cast<int>(o.second),static_cast<int>(i)});
  }
  int w=1;
  while(w*w<static_cast<int>(request.initial_values.size()))++w;
  std::sort(qs.begin(),qs.end(),[&](Q a,Q b){int x=a.l/w,y=b.l/w;if(x!=y)return x<y;return x&1?a.r>b.r:a.r<b.r;});
  std::map<std::int64_t,int>f;
  int l=0,r=0,d=0;
  std::int64_t moves=0;
  std::vector<std::int64_t>ans(qs.size());
  auto add=[&](int i){if(f[request.initial_values[static_cast<std::size_t>(i)]]++==0)++d;
  ++moves;
  };
  auto rem=[&](int i){if(--f[request.initial_values[static_cast<std::size_t>(i)]]==0)--d;
  ++moves;
  };
  for(auto q:qs){while(l>q.l)add(--l);
  while(r<q.r)add(r++);
  while(l<q.l)rem(l++);
  while(r>q.r)rem(--r);
  ans[static_cast<std::size_t>(q.i)]=d;
  }
  return MoDistinctRangeReplayResult{ans,{moves,w}
  };

}
}
