#include <vector>
namespace curriculum {
bool operator==(const PatriciaPrefixSuccessorResult& left, const PatriciaPrefixSuccessorResult& right) { return left.answers == right.answers && left.mechanism_witness == right.mechanism_witness; }
std::optional<PatriciaPrefixSuccessorResult> patricia_prefix_successor(const PatriciaPrefixSuccessorRequest& request) {
  if(request.initial_values.empty()||request.parameter<=0||request.parameter>62)return std::nullopt;
  struct N{int bit=-1;
  std::int64_t key=0;
  bool leaf=true;
  std::unique_ptr<N>c[2];
  };
  std::unique_ptr<N>root;
  auto dir=[](std::int64_t x,int b){return static_cast<int>((static_cast<std::uint64_t>(x)>>b)&1ULL);
  };
  std::int64_t branches=0;
  for(auto x:request.initial_values){if(x<0||x>=(1LL<<request.parameter))return std::nullopt;
  if(!root){root=std::make_unique<N>();
  root->key=x;
  continue;
  }
  N*leaf=root.get();
  while(!leaf->leaf)leaf=leaf->c[dir(x,leaf->bit)].get();
  if(leaf->key==x)return std::nullopt;
  auto d=static_cast<std::uint64_t>(leaf->key^x);
  int bit=0;
  while((d>>(bit+1))!=0)++bit;
  std::unique_ptr<N>*link=&root;
  while(!(*link)->leaf&&(*link)->bit>bit)link=&((*link)->c[dir(x,(*link)->bit)]);
  auto branch=std::make_unique<N>();
  branch->leaf=false;
  branch->bit=bit;
  int side=dir(x,bit);
  branch->c[1-side]=std::move(*link);
  branch->c[side]=std::make_unique<N>();
  branch->c[side]->key=x;
  *link=std::move(branch);
  ++branches;
  }
  std::function<void(const N*,std::int64_t,std::optional<std::int64_t>&)>walk=[&](const N*n,std::int64_t q,std::optional<std::int64_t>&best){if(n->leaf){if(n->key>=q&&(!best||n->key<*best))best=n->key;
  return;
  }
  walk(n->c[0].get(),q,best);
  walk(n->c[1].get(),q,best);
  };
  std::vector<std::int64_t>ans;
  for(const auto&o:request.operations){if(o.opcode!=0)return std::nullopt;
  std::optional<std::int64_t>best;
  walk(root.get(),o.first,best);
  ans.push_back(best?*best:std::numeric_limits<std::int64_t>::max());
  }
  return PatriciaPrefixSuccessorResult{ans,{branches,static_cast<std::int64_t>(request.initial_values.size())}
  };

}
}
