std::optional<PersistentKthVersionIndexResult> persistent_kth_version_index(const PersistentKthVersionIndexRequest& request) {
  if(request.initial_values.empty())return std::nullopt;
  std::vector<std::int64_t>v=request.initial_values;
  std::sort(v.begin(),v.end());
  v.erase(std::unique(v.begin(),v.end()),v.end());
  struct N{int l=0,r=0,c=0;
  };
  std::vector<N>nodes(1);
  std::function<int(int,int,int,int)>add=[&](int old,int lo,int hi,int at){int p=static_cast<int>(nodes.size());
  nodes.push_back(nodes[old]);
  ++nodes[p].c;
  if(hi-lo>1){int m=(lo+hi)/2;
  if(at<m)nodes[p].l=add(nodes[old].l,lo,m,at);
  else nodes[p].r=add(nodes[old].r,m,hi,at);
  }
  return p;
  };
  std::vector<int>roots{0};
  for(auto x:request.initial_values)roots.push_back(add(roots.back(),0,static_cast<int>(v.size()),static_cast<int>(std::lower_bound(v.begin(),v.end(),x)-v.begin())));
  std::function<int(int,int,int,int,int)>kth=[&](int x,int y,int lo,int hi,int k){if(hi-lo==1)return lo;
  int count=nodes[nodes[y].l].c-nodes[nodes[x].l].c,m=(lo+hi)/2;
  return k<=count?kth(nodes[x].l,nodes[y].l,lo,m,k):kth(nodes[x].r,nodes[y].r,m,hi,k-count);
  };
  std::vector<std::int64_t>ans;
  for(const auto&o:request.operations){if(o.opcode!=0||o.first<0||o.second<=o.first||static_cast<std::size_t>(o.second)>request.initial_values.size()||o.third<=0||o.third>o.second-o.first)return std::nullopt;
  auto chosen=v[kth(roots[o.first],roots[o.second],0,static_cast<int>(v.size()),static_cast<int>(o.third))];
  ans.push_back(chosen);
  ans.push_back(std::count(request.initial_values.begin()+o.first,request.initial_values.begin()+o.second,chosen));
  }
  return PersistentKthVersionIndexResult{ans,{static_cast<std::int64_t>(nodes.size()),static_cast<std::int64_t>(roots.size())}
  };

}
}
