bool operator==(const PersistentRangeSumDiffResult& left, const PersistentRangeSumDiffResult& right) { return left.answers == right.answers && left.mechanism_witness == right.mechanism_witness; }
std::optional<PersistentRangeSumDiffResult> persistent_range_sum_diff(const PersistentRangeSumDiffRequest& request) {
  if(request.initial_values.empty())return std::nullopt;
  struct N{int l=0,r=0;
  std::int64_t s=0;
  };
  std::vector<N>nodes(1);
  int n=static_cast<int>(request.initial_values.size());
  std::function<int(int,int)>build=[&](int l,int r){int p=static_cast<int>(nodes.size());
  nodes.push_back({});
  if(r-l==1){nodes[p].s=request.initial_values[l];
  return p;
  }
  int m=(l+r)/2;
  nodes[p].l=build(l,m);
  nodes[p].r=build(m,r);
  nodes[p].s=nodes[nodes[p].l].s+nodes[nodes[p].r].s;
  return p;
  };
  std::vector<int>roots{build(0,n)};
  std::function<int(int,int,int,int,std::int64_t)>update=[&](int old,int l,int r,int at,std::int64_t x){int p=static_cast<int>(nodes.size());
  nodes.push_back(nodes[old]);
  if(r-l==1){nodes[p].s=x;
  return p;
  }
  int m=(l+r)/2;
  if(at<m)nodes[p].l=update(nodes[old].l,l,m,at,x);
  else nodes[p].r=update(nodes[old].r,m,r,at,x);
  nodes[p].s=nodes[nodes[p].l].s+nodes[nodes[p].r].s;
  return p;
  };
  std::function<std::int64_t(int,int,int,int,int)>sum=[&](int p,int l,int r,int ql,int qr){if(qr<=l||r<=ql)return std::int64_t{0};
  if(ql<=l&&r<=qr)return nodes[p].s;
  int m=(l+r)/2;
  return sum(nodes[p].l,l,m,ql,qr)+sum(nodes[p].r,m,r,ql,qr);
  };
  std::vector<std::int64_t>ans;
  for(const auto&o:request.operations){if(o.opcode==1){if(o.first<0||static_cast<std::size_t>(o.first)>=roots.size()||o.second<0||o.second>=n)return std::nullopt;
  roots.push_back(update(roots[o.first],0,n,o.second,o.third));
  }else if(o.opcode==0){if(o.first<0||static_cast<std::size_t>(o.first)>=roots.size()||o.second<0||o.third<o.second||o.third>=n)return std::nullopt;
  ans.push_back(sum(roots[o.first],0,n,o.second,o.third+1));
  }else return std::nullopt;
  }
  return PersistentRangeSumDiffResult{ans,{static_cast<std::int64_t>(nodes.size()),static_cast<std::int64_t>(roots.size())}
  };

}
}
