bool operator==(const PrioritySearchThreeSidedResult& left, const PrioritySearchThreeSidedResult& right) { return left.answers == right.answers && left.mechanism_witness == right.mechanism_witness; }
std::optional<PrioritySearchThreeSidedResult> priority_search_three_sided(const PrioritySearchThreeSidedRequest& request) {
  if(request.initial_values.empty()||request.initial_values.size()%3)return std::nullopt;
  struct P{std::int64_t x,y,id;
  };
  std::vector<P>points;
  std::set<std::int64_t>ids;
  for(std::size_t i=0;i<request.initial_values.size();i+=3){if(!ids.insert(request.initial_values[i+2]).second)return std::nullopt;
  points.push_back({request.initial_values[i],request.initial_values[i+1],request.initial_values[i+2]});
  }
  struct N{P p;
  std::int64_t xmin,xmax;
  std::unique_ptr<N>a,b;
  };
  std::function<std::unique_ptr<N>(std::vector<P>)>build=[&](std::vector<P>v){if(v.empty())return std::unique_ptr<N>{};
  auto top=std::max_element(v.begin(),v.end(),[](P a,P b){return std::tie(a.y,a.id)<std::tie(b.y,b.id);});
  P chosen=*top;
  v.erase(top);
  auto n=std::make_unique<N>();
  n->p=chosen;
  n->xmin=n->xmax=chosen.x;
  std::sort(v.begin(),v.end(),[](P a,P b){return std::tie(a.x,a.id)<std::tie(b.x,b.id);});
  auto m=v.size()/2;
  n->a=build(std::vector<P>(v.begin(),v.begin()+m));
  n->b=build(std::vector<P>(v.begin()+m,v.end()));
  for(N*c:{n->a.get(),n->b.get()})if(c){n->xmin=std::min(n->xmin,c->xmin);
  n->xmax=std::max(n->xmax,c->xmax);
  }
  return n;
  };
  auto root=build(points);
  std::int64_t pruned=0;
  std::function<void(const N*,std::int64_t,std::int64_t,std::int64_t,std::vector<P>&)>report=[&](const N*n,std::int64_t x1,std::int64_t x2,std::int64_t floor,std::vector<P>&out){if(!n)return;
  if(n->p.y<floor||n->xmax<x1||n->xmin>x2){++pruned;
  return;
  }
  if(n->p.x>=x1&&n->p.x<=x2)out.push_back(n->p);
  report(n->a.get(),x1,x2,floor,out);
  report(n->b.get(),x1,x2,floor,out);
  };
  std::vector<std::int64_t>ans;
  for(const auto&o:request.operations){if(o.opcode!=0||o.first>o.second)return std::nullopt;
  std::vector<P>hit;
  report(root.get(),o.first,o.second,o.third,hit);
  std::sort(hit.begin(),hit.end(),[](P a,P b){return a.y!=b.y?a.y>b.y:a.id<b.id;});
  for(auto p:hit)ans.push_back(p.id);
  ans.push_back(-1);
  }
  return PrioritySearchThreeSidedResult{ans,{pruned,static_cast<std::int64_t>(ids.size())}
  };

}
}
