bool operator==(const RopeAvlRangeHashResult& left, const RopeAvlRangeHashResult& right) { return left.answers == right.answers && left.mechanism_witness == right.mechanism_witness; }
std::optional<RopeAvlRangeHashResult> rope_avl_range_hash(const RopeAvlRangeHashRequest& request) {
  constexpr std::int64_t mod=1000000007,base=257;
  struct N{unsigned char ch;
  int h=1,n=1;
  std::int64_t hash;
  std::unique_ptr<N>l,r;
  explicit N(unsigned char c):ch(c),hash(c){}
  };
  auto height=[](const std::unique_ptr<N>&n){return n?n->h:0;
  };
  auto length=[](const std::unique_ptr<N>&n){return n?n->n:0;
  };
  std::vector<std::int64_t>power{1};
  auto ensure=[&](int n){while(static_cast<int>(power.size())<=n)power.push_back(power.back()*base%mod);
  };
  std::function<void(N*)>pull=[&](N*n){ensure(1+length(n->l)+length(n->r));
  n->h=1+std::max(height(n->l),height(n->r));
  n->n=1+length(n->l)+length(n->r);
  auto left=n->l?n->l->hash:0,right=n->r?n->r->hash:0;
  n->hash=((left*base+n->ch)%mod*power[length(n->r)]+right)%mod;
  };
  std::function<std::unique_ptr<N>(std::unique_ptr<N>)>balance=[&](std::unique_ptr<N>n){pull(n.get());
  if(height(n->l)-height(n->r)>1){if(height(n->l->r)>height(n->l->l)){auto x=std::move(n->l);
  auto y=std::move(x->r);
  x->r=std::move(y->l);
  pull(x.get());
  y->l=std::move(x);
  pull(y.get());
  n->l=std::move(y);
  }
  auto x=std::move(n->l);
  n->l=std::move(x->r);
  pull(n.get());
  x->r=std::move(n);
  pull(x.get());
  return x;
  }
  if(height(n->r)-height(n->l)>1){if(height(n->r->l)>height(n->r->r)){auto x=std::move(n->r);
  auto y=std::move(x->l);
  x->l=std::move(y->r);
  pull(x.get());
  y->r=std::move(x);
  pull(y.get());
  n->r=std::move(y);
  }
  auto x=std::move(n->r);
  n->r=std::move(x->l);
  pull(n.get());
  x->l=std::move(n);
  pull(x.get());
  return x;
  }
  return n;
  };
  std::function<std::unique_ptr<N>(std::unique_ptr<N>,int,unsigned char)>insert=[&](std::unique_ptr<N>n,int at,unsigned char c){if(!n)return std::make_unique<N>(c);
  int left=length(n->l);
  if(at<=left)n->l=insert(std::move(n->l),at,c);
  else n->r=insert(std::move(n->r),at-left-1,c);
  return balance(std::move(n));
  };
  std::unique_ptr<N>root;
  for(auto x:request.initial_values){if(x<0||x>127)return std::nullopt;
  root=insert(std::move(root),length(root),x);
  }
  std::function<std::pair<std::int64_t,int>(const N*,int,int)>query=[&](const N*n,int l,int r){if(!n||l>=r)return std::pair<std::int64_t,int>{0,0};
  int left=length(n->l);
  auto a=query(n->l.get(),l,std::min(r,left));
  std::pair<std::int64_t,int>b{0,0};
  if(l<=left&&left<r)b={n->ch,1};
  auto c=query(n->r.get(),std::max(0,l-left-1),r-left-1);
  ensure(b.second+c.second);
  auto ab=std::pair<std::int64_t,int>{(a.first*power[b.second]+b.first)%mod,a.second+b.second};
  ensure(c.second);
  return std::pair<std::int64_t,int>{(ab.first*power[c.second]+c.first)%mod,ab.second+c.second};
  };
  std::vector<std::int64_t>ans;
  std::int64_t splices=0;
  for(const auto&o:request.operations){if(o.opcode==1){if(o.first<0||o.first>length(root)||o.second<0||o.second>127)return std::nullopt;
  root=insert(std::move(root),o.first,o.second);
  ++splices;
  }else if(o.opcode==0){if(o.first<0||o.second<o.first||o.second>length(root))return std::nullopt;
  ans.push_back(query(root.get(),o.first,o.second).first);
  }else return std::nullopt;
  }
  return RopeAvlRangeHashResult{ans,{splices,length(root),height(root)}
  };

}
}
