std::optional<ScapegoatRangeRebuilderResult> scapegoat_range_rebuilder(const ScapegoatRangeRebuilderRequest& request) {
  struct N{std::int64_t k;
  std::unique_ptr<N>l,r;
  int s=1;
  explicit N(std::int64_t x):k(x){}
  };
  std::unique_ptr<N>root;
  std::int64_t rebuilds=0;

  std::function<int(const std::unique_ptr<N>&)> size=[&](const std::unique_ptr<N>&n){return n?n->s:0;
  };
  std::function<void(N*)>pull=[&](N*n){if(n)n->s=1+size(n->l)+size(n->r);
  };

  std::function<void(std::unique_ptr<N>&,std::vector<std::int64_t>&)>flat=[&](std::unique_ptr<N>&n,std::vector<std::int64_t>&v){if(!n)return;
  flat(n->l,v);
  v.push_back(n->k);
  flat(n->r,v);
  };

  std::function<std::unique_ptr<N>(const std::vector<std::int64_t>&,int,int)>build=[&](const std::vector<std::int64_t>&v,int a,int b)->std::unique_ptr<N>{if(a>=b)return {};
  int m=a+(b-a)/2;
  auto n=std::make_unique<N>(v[static_cast<std::size_t>(m)]);
  n->l=build(v,a,m);
  n->r=build(v,m+1,b);
  pull(n.get());
  return n;
  };

  auto add=[&](std::int64_t x){std::function<bool(std::unique_ptr<N>&,int)>ins=[&](std::unique_ptr<N>&n,int d){if(!n){n=std::make_unique<N>(x);
  return d<=8;
  }
  if(x==n->k)return false;
  bool ok=ins(x<n->k?n->l:n->r,d+1);
  pull(n.get());
  return ok;
  };
  if(!ins(root,0))return false;
  if(root&&9*std::max(size(root->l),size(root->r))>7*root->s){std::vector<std::int64_t>v;
  flat(root,v);
  root=build(v,0,static_cast<int>(v.size()));
  ++rebuilds;
  }
  return true;
  };
  for(auto x:request.initial_values)if(!add(x))return std::nullopt;
  std::vector<std::int64_t>ans;
  for(const auto&o:request.operations){if(o.opcode!=0||o.first>o.second)return std::nullopt;
  std::function<int(const N*,std::int64_t)>less=[&](const N*n,std::int64_t x){if(!n)return 0;
  if(n->k>=x)return less(n->l.get(),x);
  return 1+size(n->l)+less(n->r.get(),x);
  };
  ans.push_back(less(root.get(),o.second+1)-less(root.get(),o.first));
  }
  return ScapegoatRangeRebuilderResult{ans,{rebuilds,size(root)}
  };

}
