std::optional<SegmentTreeFirstPrefixResult> segment_tree_first_prefix(const SegmentTreeFirstPrefixRequest& request) {
  if(request.initial_values.empty())return std::nullopt;
  using P=std::pair<std::int64_t,std::int64_t>;
  std::size_t n=1;
  while(n<request.initial_values.size())n*=2;
  const auto neg=std::numeric_limits<std::int64_t>::min()/4;
  std::vector<P>t(2*n,{0,neg});
  for(std::size_t i=0;i<request.initial_values.size();++i)t[n+i]={request.initial_values[i],request.initial_values[i]};
  auto combine=[](P a,P b){return P{a.first+b.first,std::max(a.second,a.first+b.second)};
  };
  for(std::size_t p=n;p-->1;)t[p]=combine(t[2*p],t[2*p+1]);
  std::vector<std::int64_t>ans;
  std::int64_t desc=0;
  for(const auto&o:request.operations){if(o.opcode==1){if(o.first<0||static_cast<std::size_t>(o.first)>=request.initial_values.size())return std::nullopt;
  std::size_t p=n+o.first;
  t[p]={o.second,o.second};
  while((p/=2)>0)t[p]=combine(t[2*p],t[2*p+1]);
  }else if(o.opcode==0){if(t[1].second<o.first){ans.push_back(-1);
  continue;
  }
  std::size_t p=1;
  std::int64_t before=0;
  while(p<n){++desc;
  if(before+t[2*p].second>=o.first)p*=2;
  else{before+=t[2*p].first;
  p=2*p+1;
  }
  }
  ans.push_back(static_cast<std::int64_t>(p-n));
  }else return std::nullopt;
  }
  return SegmentTreeFirstPrefixResult{ans,{desc,static_cast<std::int64_t>(n)}
  };

}
}
