bool operator==(const SplayNeighborCursorResult& left, const SplayNeighborCursorResult& right) { return left.answers == right.answers && left.mechanism_witness == right.mechanism_witness; }
std::optional<SplayNeighborCursorResult> splay_neighbor_cursor(const SplayNeighborCursorRequest& request) {
  struct N{std::int64_t k;
  N*l=nullptr,*r=nullptr,*p=nullptr;
  };
  std::vector<std::unique_ptr<N>> pool;
  N*root=nullptr;
  std::int64_t turns=0;

  auto rot=[&](N*x){N*p=x->p;
  N*g=p->p;
  if(x==p->l){p->l=x->r;
  if(x->r)x->r->p=p;
  x->r=p;
  }else{p->r=x->l;
  if(x->l)x->l->p=p;
  x->l=p;
  }
  p->p=x;
  x->p=g;
  if(g){if(g->l==p)g->l=x;
  else g->r=x;
  }else root=x;
  ++turns;
  };

  auto splay=[&](N*x){while(x&&x->p){N*p=x->p;
  N*g=p->p;
  if(!g)rot(x);
  else if((g->l==p)==(p->l==x)){rot(p);
  rot(x);
  }else{rot(x);
  rot(x);
  }
  }
  };

  for(auto x:request.initial_values){if(!root){pool.push_back(std::make_unique<N>());
  root=pool.back().get();
  root->k=x;
  continue;
  }
  N*n=root,*p=nullptr;
  while(n){p=n;
  if(x==n->k)return std::nullopt;
  n=x<n->k?n->l:n->r;
  }
  pool.push_back(std::make_unique<N>());
  N*z=pool.back().get();
  z->k=x;
  z->p=p;
  (x<p->k?p->l:p->r)=z;
  splay(z);
  }
  std::vector<std::int64_t>ans;

  for(const auto&o:request.operations){if(o.opcode!=0)return std::nullopt;
  N*n=root,*last=nullptr,*pred=nullptr,*succ=nullptr;
  while(n){last=n;
  if(n->k<o.first){pred=n;
  n=n->r;
  }else{succ=n;
  n=n->l;
  }
  }
  if(last)splay(last);
  ans.push_back(pred?pred->k:std::numeric_limits<std::int64_t>::min());
  ans.push_back(succ?succ->k:std::numeric_limits<std::int64_t>::max());
  ans.push_back(root?root->k:0);
  }
  return SplayNeighborCursorResult{ans,{turns}
  };

}
}
