  std::vector<std::int64_t>a=request.initial_values,ans;
  std::size_t w=1;
  while(w*w<a.size())++w;
  std::vector<std::vector<std::int64_t>>b((a.size()+w-1)/w);
  auto rebuild=[&](std::size_t q){b[q].assign(a.begin()+static_cast<std::ptrdiff_t>(q*w),a.begin()+static_cast<std::ptrdiff_t>(std::min(a.size(),(q+1)*w)));
  std::sort(b[q].begin(),b[q].end());
  };
  for(std::size_t q=0;q<b.size();++q)rebuild(q);
  std::int64_t blocks=0;
  for(const auto&o:request.operations){if(o.opcode==1){if(o.first<0||static_cast<std::size_t>(o.first)>=a.size())return std::nullopt;
  a[static_cast<std::size_t>(o.first)]=o.second;
  rebuild(static_cast<std::size_t>(o.first)/w);
  }else if(o.opcode==0){if(o.first<0||o.second<o.first||static_cast<std::size_t>(o.second)>=a.size())return std::nullopt;
