  c+=std::lower_bound(q.begin(),q.end(),o.third)-q.begin();
  i+=static_cast<std::int64_t>(w);
  ++blocks;
  }else{c+=a[static_cast<std::size_t>(i)]<o.third;
  ++i;
  }
  }
  ans.push_back(c);
  }else return std::nullopt;
  }
  return SqrtDecompositionRankUpdatesResult{ans,{blocks,static_cast<std::int64_t>(w)}
  };

}
