bool operator==(const TreapSplitRankLedgerResult& left, const TreapSplitRankLedgerResult& right) { return left.answers == right.answers && left.mechanism_witness == right.mechanism_witness; }
std::optional<TreapSplitRankLedgerResult> treap_split_rank_ledger(const TreapSplitRankLedgerRequest& request) {
  struct N{std::int64_t k;
  std::uint64_t p;
  int n=1,s=1;
  std::unique_ptr<N> l,r;
  N(std::int64_t x,std::uint64_t q):k(x),p(q){}
  };

  auto sz=[](const std::unique_ptr<N>& n){return n?n->s:0;
  };

  std::function<void(N*)> pull=[&](N* n){if(n)n->s=n->n+sz(n->l)+sz(n->r);
  };

  std::function<void(std::unique_ptr<N>,std::int64_t,std::unique_ptr<N>&,std::unique_ptr<N>&)> split;

  split=[&](std::unique_ptr<N> n,std::int64_t k,std::unique_ptr<N>& a,std::unique_ptr<N>& b){if(!n){a.reset();
  b.reset();
  return;
  }
  if(n->k<k){split(std::move(n->r),k,n->r,b);
  pull(n.get());
  a=std::move(n);
  }else{split(std::move(n->l),k,a,n->l);
  pull(n.get());
  b=std::move(n);
  }
  };

  std::function<std::unique_ptr<N>(std::unique_ptr<N>,std::unique_ptr<N>)> merge=[&](std::unique_ptr<N> a,std::unique_ptr<N> b)->std::unique_ptr<N>{if(!a)return b;
  if(!b)return a;
  if(a->p>b->p){a->r=merge(std::move(a->r),std::move(b));
  pull(a.get());
  return a;
  }
  b->l=merge(std::move(a),std::move(b->l));
  pull(b.get());
  return b;
  };

  std::unique_ptr<N> root;
  std::uint64_t seed=0x9e3779b97f4a7c15ULL;
  std::int64_t rotations=0;

  auto insert=[&](std::int64_t x){std::unique_ptr<N>a,b,c;
  split(std::move(root),x,a,b);
  if(x!=std::numeric_limits<std::int64_t>::max())split(std::move(b),x+1,b,c);
  if(b){++b->n;
  pull(b.get());
  }else{seed^=seed<<7;
  seed^=seed>>9;
  b=std::make_unique<N>(x,seed);
  }
  root=merge(merge(std::move(a),std::move(b)),std::move(c));
  ++rotations;
  };

  for(auto x:request.initial_values)insert(x);
  std::vector<std::int64_t> ans;

  for(const auto&o:request.operations){if(o.second!=0||o.third!=0)return std::nullopt;
  if(o.opcode==1)insert(o.first);
  else if(o.opcode==0){N*n=root.get();
  std::int64_t rank=0;
  while(n){if(o.first<=n->k)n=n->l.get();
  else{rank+=sz(n->l)+n->n;
  n=n->r.get();
  }
  }
  ans.push_back(rank);
  }else return std::nullopt;
  }
  return TreapSplitRankLedgerResult{ans,{rotations,sz(root)}
  };

}
}
