std::optional<VanEmdeBoasSuccessorSetResult> van_emde_boas_successor_set(const VanEmdeBoasSuccessorSetRequest& request) {
  if(request.parameter<2||(request.parameter&(request.parameter-1))!=0)return std::nullopt;
  struct V{int u,mn=-1,mx=-1,bits=0,low=0;
  std::unique_ptr<V>summary;
  std::vector<std::unique_ptr<V>>cluster;
  explicit V(int n):u(n){if(u>2){int b=0;
  while((1<<b)<u)++b;
  bits=b/2;
  low=1<<bits;
  cluster.resize(1U<<(b-bits));
  }
  }
  };
  std::int64_t allocated=0;
  std::function<bool(V&,int)>insert=[&](V&v,int x){if(v.mn==x||v.mx==x)return false;
  if(v.mn<0){v.mn=v.mx=x;
  return true;
  }
  if(x<v.mn)std::swap(x,v.mn);
  if(v.u>2){int h=x>>v.bits,l=x&(v.low-1);
  if(!v.cluster[h])v.cluster[h]=std::make_unique<V>(v.low);
  if(v.cluster[h]->mn<0){if(!v.summary)v.summary=std::make_unique<V>(v.cluster.size());
  insert(*v.summary,h);
  v.cluster[h]->mn=v.cluster[h]->mx=l;
  ++allocated;
  }else if(!insert(*v.cluster[h],l))return false;
  }
  v.mx=std::max(v.mx,x);
  return true;
  };
  std::function<int(const V&,int)>successor=[&](const V&v,int x){if(v.mn<0)return -1;
  if(x<v.mn)return v.mn;
  if(v.u==2)return x==0&&v.mx==1?1:-1;
  int h=x>>v.bits,l=x&(v.low-1);
  if(v.cluster[h]&&v.cluster[h]->mx>l){int z=successor(*v.cluster[h],l);
  return (h<<v.bits)+z;
  }
  if(!v.summary)return -1;
  int nh=successor(*v.summary,h);
  return nh<0?-1:(nh<<v.bits)+v.cluster[nh]->mn;
  };
  V root(request.parameter);
  for(auto x:request.initial_values)if(x<0||x>=request.parameter||!insert(root,x))return std::nullopt;
  std::vector<std::int64_t>ans;
  for(const auto&o:request.operations){if(o.opcode!=0||o.first<0||o.first>=request.parameter)return std::nullopt;
  ans.push_back(successor(root,o.first));
  }
  return VanEmdeBoasSuccessorSetResult{ans,{allocated,root.mx-root.mn+1}
  };

}
}
