  (((a[i]>>bit)&1)?hi:lo).push_back(a[i]);
  }
  mid.push_back(lo.size());
  lo.insert(lo.end(),hi.begin(),hi.end());
  a=std::move(lo);
  zero.push_back(std::move(p));
  }
  std::vector<std::int64_t>ans;
