  if(request.initial_values.empty())return std::nullopt;
  struct N{std::int64_t lo,hi;
  std::vector<int>left;
  std::unique_ptr<N>a,b;
  };
  std::function<std::unique_ptr<N>(std::vector<std::int64_t>,std::int64_t,std::int64_t)>build=[&](std::vector<std::int64_t>v,std::int64_t lo,std::int64_t hi){auto n=std::make_unique<N>();
  n->lo=lo;
  n->hi=hi;
  n->left={0};
  if(lo==hi||v.empty())return n;
  auto m=lo+(hi-lo)/2;
  std::vector<std::int64_t>x,y;
  for(auto z:v){(z<=m?x:y).push_back(z);
  n->left.push_back(x.size());
  }
  n->a=build(std::move(x),lo,m);
  n->b=build(std::move(y),m+1,hi);
  return n;
  };
  auto mm=std::minmax_element(request.initial_values.begin(),request.initial_values.end());
  auto root=build(request.initial_values,*mm.first,*mm.second);
  std::int64_t routed=0;
  std::function<int(const N*,int,int,std::int64_t)>less=[&](const N*n,int l,int r,std::int64_t x){if(!n||l>=r||x<=n->lo)return 0;
  if(n->hi<x)return r-l;
  ++routed;
  if(n->lo==n->hi)return 0;
  int al=n->left[l],ar=n->left[r];
  return less(n->a.get(),al,ar,x)+less(n->b.get(),l-al,r-ar,x);
  };
  std::vector<std::int64_t>ans;
  for(const auto&o:request.operations){if(o.opcode!=0||o.first<0||o.second<o.first||static_cast<std::size_t>(o.second)>=request.initial_values.size())return std::nullopt;
