  struct N{std::int64_t k;
  int c=1,h=1,s=1;
  std::unique_ptr<N>l,r;
  explicit N(std::int64_t x):k(x){}
  };
  std::unique_ptr<N>root;
  std::int64_t turns=0;
  auto h=[](const std::unique_ptr<N>&n){return n?n->h:0;
  };
  auto sz=[](const std::unique_ptr<N>&n){return n?n->s:0;
  };
  auto pull=[&](N*n){n->h=1+std::max(h(n->l),h(n->r));
  n->s=n->c+sz(n->l)+sz(n->r);
  };
  std::function<std::unique_ptr<N>(std::unique_ptr<N>,std::int64_t)>ins;

  ins=[&](std::unique_ptr<N>n,std::int64_t x)->std::unique_ptr<N>{if(!n)return std::make_unique<N>(x);
  if(x==n->k)++n->c;
  else if(x<n->k)n->l=ins(std::move(n->l),x);
  else n->r=ins(std::move(n->r),x);
  pull(n.get());
  int b=h(n->l)-h(n->r);
  auto rr=[&](std::unique_ptr<N>y){auto x=std::move(y->l);
  y->l=std::move(x->r);
  pull(y.get());
  x->r=std::move(y);
  pull(x.get());
  ++turns;
  return x;
  };
  auto rl=[&](std::unique_ptr<N>x){auto y=std::move(x->r);
  x->r=std::move(y->l);
  pull(x.get());
  y->l=std::move(x);
  pull(y.get());
  ++turns;
  return y;
  };
  if(b>1){if(x>n->l->k)n->l=rl(std::move(n->l));
  return rr(std::move(n));
  }
  if(b<-1){if(x<n->r->k)n->r=rr(std::move(n->r));
  return rl(std::move(n));
  }
  return n;
  };
  for(auto x:request.initial_values)root=ins(std::move(root),x);
  std::vector<std::int64_t>ans;
  for(const auto&o:request.operations){if(o.opcode!=0||o.first<=0||o.first>sz(root))return std::nullopt;
  int k=static_cast<int>(o.first);
  N*n=root.get();
  while(n){if(k<=sz(n->l))n=n->l.get();
  else if(k<=sz(n->l)+n->c){ans.push_back(n->k);
