Result bad(){return {false,false,-1,-1};}
Result ok(bool member,long long value,long long witness){return {true,member,value,witness};}
long long gcdll(long long a,long long b){if(a<0)a=-a;if(b<0)b=-b;while(b){long long r=a%b;a=b;b=r;}return a;}
long long egcd(long long a,long long b,long long& x,long long& y){if(b==0){x=a<0?-1:1;y=0;return a<0?-a:a;}long long x1=0,y1=0;long long g=egcd(b,a%b,x1,y1);x=y1;y=x1-(a/b)*y1;return g;}
}
Result analyze_linear_congruence_solver(long long a, long long b, long long modulus){if(modulus<2||modulus>1000000000||a<-1000000000||a>1000000000||b<-1000000000||b>1000000000)return bad();long long g=gcdll(a,modulus);if(b%g!=0)return ok(false,0,g);long long m=modulus/g,x=0,y=0;egcd(a/g,m,x,y);long long r=((b/g)%m*x)%m;if(r<0)r+=m;return ok(true,r,m);}
}
