std::optional<ComplexValue> ComplexImpedanceReduction::reduce(const std::vector<ImpedanceToken>& postfix) const {
// CORE_BEGIN: postfix stack reduction with distinct series and reciprocal parallel operations
std::vector<C> stack;
for(const auto&token:postfix){if(token.kind=='V'){if(!finite_c(token.value))return std::nullopt;
stack.push_back(token.value);continue;}if((token.kind!='S'&&token.kind!='P')||stack.size()<2)return std::nullopt;
