if(token.kind=='S')stack.push_back(add_c(left,right));else{auto il=div_c({1,0},left),ir=div_c({1,0},right);auto result=il&&ir?div_c({1,0},add_c(*il,*ir)):std::nullopt;
if(!result)return std::nullopt;
stack.push_back(*result);}}if(stack.size()!=1||!finite_c(stack[0]))return std::nullopt;
return stack[0];
// CORE_END
}
