// CORE_BEGIN stable weighted median selection
if((input.marks.size()>4096))return std::nullopt;
if(input.marks.empty())return std::nullopt;
auto v=input.marks;
U total=0,t=0;
for(auto m:v){if(m.value<0||m.weight==0||!add(total,m.weight,t))return std::nullopt;
