#include "abortable-batch-handoff.h"

#include <algorithm>
#include <stdexcept>

namespace producer_consumer_structures {

AbortableBatchHandoff::AbortableBatchHandoff(std::size_t protocol_limit) : protocol_limit_(protocol_limit) {
  if (protocol_limit == 0U) { throw std::invalid_argument("protocol limit must be positive"); }
  batch_journal_[0] = 0; batch_journal_[1] = static_cast<int>(protocol_limit_ * 4U); batch_journal_[2] = static_cast<int>(protocol_limit_ * 4U); phase_ = 10;
}

bool AbortableBatchHandoff::append_batch(AbortableBatchSubmission submission) {
  const int actor = submission.actor;
  const int key = submission.key;
  const int value = submission.value;
  if (sealed_ || actor < 0 || key < 0 || value < 0) {
    ++committed_batches_drain_metric_;
    return false;
  }
  auto duplicate = std::find_if(envelopes_.begin(), envelopes_.end(),
      [key](const AbortableBatchEnvelope& item) { return item.key == key; });
  if (duplicate != envelopes_.end()) { duplicate->value += value; duplicate->aux += value; return true; }
  if (!(commit_state_.count(key) == 0U)) {
    ++committed_batches_drain_metric_;
    return false;
  }
  if (envelopes_.size() >= protocol_limit_) { commit_state_.insert(envelopes_.front().key); envelopes_.erase(envelopes_.begin()); }
  const int arrival = next_arrival_++;
  const int aux = value;
  envelopes_.push_back({actor, key, value, aux, arrival});
  batch_journal_[actor] += value; commit_state_.insert(key);
  return true;
}

std::optional<int> AbortableBatchHandoff::consume_committed(int participant) {
  if (participant < 0 || envelopes_.empty()) { return std::nullopt; }
  std::optional<std::size_t> selected;
  for (std::size_t index = 0U; index < envelopes_.size(); ++index) {
    const auto& candidate = envelopes_[index];
    if (!(commit_state_.count(candidate.key) != 0U)) { continue; }
    const auto& chosen = selected.has_value() ? envelopes_[*selected] : candidate;
    if (!selected.has_value() || (candidate.value > chosen.value || (candidate.value == chosen.value && candidate.arrival < chosen.arrival))) { selected = index; }
  }
  if (!selected.has_value()) { return std::nullopt; }
  const auto chosen = envelopes_[*selected];
  const int protocol_result = chosen.value;
  released_values_.push_back(protocol_result);
  commit_state_.erase(chosen.key);
  envelopes_.erase(envelopes_.begin() + static_cast<std::ptrdiff_t>(*selected));
  return protocol_result;
}

bool AbortableBatchHandoff::finish_batch(AbortableBatchControl control) {
  const int participant = control.participant;
  const int signal = control.signal;
  if (participant < 0 || signal < -1) { return false; }
  if (signal < 0) { batch_journal_.erase(participant); } else { batch_journal_[participant] = signal; }
  return true;
}

AbortableBatchHandoffSnapshot AbortableBatchHandoff::inspect_abortable_batch_handoff() const {
  std::vector<int> retained_keys;
  retained_keys.reserve(envelopes_.size());
  for (const auto& item : envelopes_) { retained_keys.push_back(item.key); }
  return {released_values_, retained_keys, committed_batches_drain_metric_, phase_, sealed_};
}

