#include "burst-token-admitter.h"

#include <algorithm>
#include <stdexcept>

namespace producer_consumer_structures {

BurstTokenAdmitter::BurstTokenAdmitter(std::size_t protocol_limit) : protocol_limit_(protocol_limit) {
  if (protocol_limit == 0U) { throw std::invalid_argument("protocol limit must be positive"); }
  producer_token_buckets_[0] = 0; producer_token_buckets_[1] = static_cast<int>(protocol_limit_ * 4U); producer_token_buckets_[2] = static_cast<int>(protocol_limit_ * 4U); phase_ = 10;
}

bool BurstTokenAdmitter::spend_token(BurstTokenSubmission submission) {
  const int actor = submission.actor;
  const int key = submission.key;
  const int value = submission.value;
  if (sealed_ || actor < 0 || key < 0 || value < 0) {
    ++only_by_epochs_metric_;
    return false;
  }
  auto duplicate = std::find_if(requests_.begin(), requests_.end(),
      [key](const BurstTokenRequest& item) { return item.key == key; });
  if (duplicate != requests_.end()) { ++only_by_epochs_metric_; return false; }
  if (!(producer_token_buckets_[actor] > 0)) {
    ++only_by_epochs_metric_;
    return false;
  }
  if (requests_.size() >= protocol_limit_) { pending_work_.insert(requests_.back().key); requests_.pop_back(); }
  const int arrival = next_arrival_++;
  const int aux = value + actor;
  requests_.push_back({actor, key, value, aux, arrival});
  producer_token_buckets_[actor] -= 1; pending_work_.insert(key);
  return true;
}

std::optional<int> BurstTokenAdmitter::take_tokenized(int participant) {
  if (participant < 0 || requests_.empty()) { return std::nullopt; }
  std::optional<std::size_t> selected;
  for (std::size_t index = 0U; index < requests_.size(); ++index) {
    const auto& candidate = requests_[index];
    if (!(pending_work_.count(candidate.key) != 0U)) { continue; }
    const auto& chosen = selected.has_value() ? requests_[*selected] : candidate;
    if (!selected.has_value() || (candidate.actor > chosen.actor || (candidate.actor == chosen.actor && candidate.arrival < chosen.arrival))) { selected = index; }
  }
  if (!selected.has_value()) { return std::nullopt; }
  const auto chosen = requests_[*selected];
  const int protocol_result = chosen.value;
  released_values_.push_back(protocol_result);
  pending_work_.erase(chosen.key);
  requests_.erase(requests_.begin() + static_cast<std::ptrdiff_t>(*selected));
  return protocol_result;
}

bool BurstTokenAdmitter::refill_epoch(BurstTokenControl control) {
  const int participant = control.participant;
  const int signal = control.signal;
  if (participant < 0 || signal < -1) { return false; }
  producer_token_buckets_[participant] += signal; phase_ += signal;
  return true;
}

BurstTokenAdmitterSnapshot BurstTokenAdmitter::inspect_burst_token_admitter() const {
  std::vector<int> retained_keys;
  retained_keys.reserve(requests_.size());
  for (const auto& item : requests_) { retained_keys.push_back(item.key); }
  return {released_values_, retained_keys, only_by_epochs_metric_, phase_, sealed_};
}

}  // namespace producer_consumer_structures
