    ++after_terminal_failure_metric_;
    return false;
  }
  if (deliveries_.size() >= protocol_limit_) { compensation_emitted_bit_.insert(deliveries_.front().key); deliveries_.erase(deliveries_.begin()); }
  const int arrival = next_arrival_++;
  const int aux = key + phase_;
