  auto duplicate = std::find_if(requests_.begin(), requests_.end(),
      [key](const DeadlineShedRequest& item) { return item.key == key; });
  if (duplicate != requests_.end()) { duplicate->value = value; return true; }
  if (!(key >= phase_)) {
    ++under_full_admission_metric_;
    return false;
