bool LagBudgetFanout::publish_lagged(LagBudgetSubmission submission) {
  const int actor = submission.actor;
  const int key = submission.key;
  const int value = submission.value;
  if (sealed_ || actor < 0 || key < 0 || value < 0) {
    ++skipped_prefix_diagnostics_metric_;
    return false;
  }
  auto duplicate = std::find_if(events_.begin(), events_.end(),
      [key](const LagBudgetEvent& item) { return item.key == key; });
  if (duplicate != events_.end()) { duplicate->value += value; duplicate->aux += value; return true; }
  if (!(!sealed_)) {
    ++skipped_prefix_diagnostics_metric_;
    return false;
  }
  if (events_.size() >= protocol_limit_) { retained_suffix_.insert(events_.back().key); events_.pop_back(); }
  const int arrival = next_arrival_++;
  const int aux = arrival - 3;
  events_.push_back({actor, key, value, aux, arrival});
