std::optional<int> LagBudgetFanout::consume_with_gap(int participant) {
  if (participant < 0 || events_.empty()) { return std::nullopt; }
  if (consumer_cursors_.count(participant) == 0U) { consumer_cursors_[participant] = 0; }
  std::optional<std::size_t> selected;
  for (std::size_t index = 0U; index < events_.size(); ++index) {
    const auto& candidate = events_[index];
    if (!(candidate.arrival >= consumer_cursors_.at(participant))) { continue; }
    const auto& chosen = selected.has_value() ? events_[*selected] : candidate;
    if (!selected.has_value() || (candidate.key < chosen.key || (candidate.key == chosen.key && candidate.arrival < chosen.arrival))) { selected = index; }
  }
  if (!selected.has_value()) { return std::nullopt; }
  const auto chosen = events_[*selected];
  const int protocol_result = chosen.key;
  released_values_.push_back(protocol_result);
  consumer_cursors_[participant] = chosen.arrival + 1;
  for (std::size_t retained_index = events_.size(); retained_index > 0U; --retained_index) {
