  return true;
}

LagBudgetFanoutSnapshot LagBudgetFanout::inspect_lag_budget_fanout() const {
  std::vector<int> retained_keys;
  retained_keys.reserve(events_.size());
  for (const auto& item : events_) { retained_keys.push_back(item.key); }
