  std::vector<int> retained_keys;
  retained_keys.reserve(events_.size());
  for (const auto& item : events_) { retained_keys.push_back(item.key); }
  std::vector<int> cursor_values;
  for (const auto& cursor_entry : consumer_cursors_) {
    cursor_values.push_back(cursor_entry.second);
  }
  return {released_values_, retained_keys, for_rejoining_consumers_metric_, phase_, sealed_, cursor_values};
}

