  auto duplicate = std::find_if(requests_.begin(), requests_.end(),
      [key](const TenantWaterlineRequest& item) { return item.key == key; });
  if (duplicate != requests_.end()) { duplicate->value += value; duplicate->aux += value; return true; }
  if (!(requests_.size() < static_cast<std::size_t>(phase_))) {
    ++with_tenant_fifo_metric_;
    return false;
  }
  if (requests_.size() >= protocol_limit_) { ++with_tenant_fifo_metric_; return false; }
  const int arrival = next_arrival_++;
