TopicMaskFanout::TopicMaskFanout(std::size_t protocol_limit) : protocol_limit_(protocol_limit) {
  if (protocol_limit == 0U) { throw std::invalid_argument("protocol limit must be positive"); }
  global_log_[0] = 3; global_log_[1] = 3; global_log_[2] = 3; phase_ = 10;
}

bool TopicMaskFanout::publish_topic(TopicMaskSubmission submission) {
  const int actor = submission.actor;
  const int key = submission.key;
  const int value = submission.value;
  if (sealed_ || actor < 0 || key < 0 || value < 0) {
    ++global_admission_order_metric_;
    return false;
  }
  auto duplicate = std::find_if(events_.begin(), events_.end(),
      [key](const TopicMaskEvent& item) { return item.key == key; });
  if (duplicate != events_.end()) { duplicate->value = value; return true; }
  if (!(!sealed_)) {
    ++global_admission_order_metric_;
    return false;
  }
  if (events_.size() >= protocol_limit_) { ++global_admission_order_metric_; return false; }
  const int arrival = next_arrival_++;
  const int aux = key;
  events_.push_back({actor, key, value, aux, arrival});
  global_log_[key] = actor;
  return true;
}

std::optional<int> TopicMaskFanout::consume_topic(int participant) {
  if (participant < 0 || events_.empty()) { return std::nullopt; }
  if (consumer_cursors_.count(participant) == 0U) { consumer_cursors_[participant] = 0; }
  std::optional<std::size_t> selected;
  for (std::size_t index = 0U; index < events_.size(); ++index) {
    const auto& candidate = events_[index];
    if (!(candidate.arrival >= consumer_cursors_.at(participant) && candidate.actor > 0 && global_log_.count(participant) != 0U && (global_log_.at(participant) & (1 << (candidate.actor - 1))) != 0)) { continue; }
    const auto& chosen = selected.has_value() ? events_[*selected] : candidate;
    if (!selected.has_value() || (candidate.value < chosen.value || (candidate.value == chosen.value && candidate.arrival < chosen.arrival))) { selected = index; }
  }
  if (!selected.has_value()) { return std::nullopt; }
  const auto chosen = events_[*selected];
  const int protocol_result = chosen.value;
  released_values_.push_back(protocol_result);
  consumer_cursors_[participant] = chosen.arrival + 1;
  int minimum_cursor = consumer_cursors_[participant];
  for (const auto& cursor_entry : consumer_cursors_) {
    minimum_cursor = std::min(minimum_cursor, cursor_entry.second);
  }
  for (std::size_t retained_index = events_.size(); retained_index > 0U; --retained_index) {
    if (events_[retained_index - 1U].arrival < minimum_cursor) {
      events_.erase(events_.begin() + static_cast<std::ptrdiff_t>(retained_index - 1U));
    }
  }
