```
#include "work-steal-lease-board.h"

#include <algorithm>
#include <stdexcept>

namespace producer_consumer_structures {

WorkStealLeaseBoard::WorkStealLeaseBoard(std::size_t protocol_limit) : protocol_limit_(protocol_limit) {
  if (protocol_limit == 0U) { throw std::invalid_argument("protocol limit must be positive"); }
  origin_lanes_[0] = 0; origin_lanes_[1] = static_cast<int>(protocol_limit_ * 4U); origin_lanes_[2] = static_cast<int>(protocol_limit_ * 4U); phase_ = 10;
}

bool WorkStealLeaseBoard::post_stealable(WorkStealSubmission submission) {
  const int actor = submission.actor;
  const int key = submission.key;
  const int value = submission.value;
  if (sealed_ || actor < 0 || key < 0 || value < 0) {
    ++with_origin_return_metric_;
    return false;
  }
  auto duplicate = std::find_if(jobs_.begin(), jobs_.end(),
      [key](const WorkStealJob& item) { return item.key == key; });
  if (duplicate != jobs_.end()) { duplicate->value += value; duplicate->aux += value; return true; }
  if (!(!sealed_)) {
    ++with_origin_return_metric_;
    return false;
  }
  if (jobs_.size() >= protocol_limit_) { ++with_origin_return_metric_; return false; }
  const int arrival = next_arrival_++;
  const int aux = phase_ + actor;
  jobs_.push_back({actor, key, value, aux, arrival});
  origin_lanes_[key] = actor;
  return true;
}

std::optional<int> WorkStealLeaseBoard::steal_oldest(int participant) {
  if (participant < 0 || jobs_.empty()) { return std::nullopt; }
  std::optional<std::size_t> selected;
  for (std::size_t index = 0U; index < jobs_.size(); ++index) {
    const auto& candidate = jobs_[index];
    if (!(origin_lanes_.count(candidate.key) != 0U)) { continue; }
    const auto& chosen = selected.has_value() ? jobs_[*selected] : candidate;
    if (!selected.has_value() || (((candidate.actor + phase_) % 7) < ((chosen.actor + phase_) % 7))) { selected = index; }
  }
  if (!selected.has_value()) { return std::nullopt; }
  const auto chosen = jobs_[*selected];
  const int protocol_result = chosen.value;
  released_values_.push_back(protocol_result);
  origin_lanes_[chosen.key] = participant;
  jobs_.erase(jobs_.begin() + static_cast<std::ptrdiff_t>(*selected));
  return protocol_result;
}

bool WorkStealLeaseBoard::expire_steal_lease(WorkStealControl control) {
  const int participant = control.participant;
  const int signal = control.signal;
  if (participant < 0 || signal < -1) { return false; }
  origin_lanes_.erase(participant); phase_ += signal;
  return true;
}

WorkStealLeaseBoardSnapshot WorkStealLeaseBoard::inspect_work_steal_lease_board() const {
  std::vector<int> retained_keys;
  retained_keys.reserve(jobs_.size());
  for (const auto& item : jobs_) { retained_keys.push_back(item.key); }
  return {released_values_, retained_keys, with_origin_return_metric_, phase_, sealed_};
}

}  // namespace producer_consumer_structures
