SegmentRaster raster_segment(GridPoint from, GridPoint to, char ink) {
if (ink < '!' || ink > '~' || from.x < -64 || from.x > 64 || from.y < -64 || from.y > 64 || to.x < -64 || to.x > 64 || to.y < -64 || to.y > 64) return {};

const int min_x = std::min(from.x,to.x), max_x = std::max(from.x,to.x), min_y = std::min(from.y,to.y), max_y = std::max(from.y,to.y);
 SegmentRaster out;
 out.valid = true;
 out.origin = {min_x,min_y};
 out.rows.assign(static_cast<std::size_t>(max_y-min_y+1), std::string(static_cast<std::size_t>(max_x-min_x+1), '.'));

int x = from.x, y = from.y;
 const int dx = std::abs(to.x-from.x), sx = from.x < to.x ? 1 : -1, dy = -std::abs(to.y-from.y), sy = from.y < to.y ? 1 : -1;
 int error = dx + dy;

for (;;) { out.rows[static_cast<std::size_t>(y-min_y)][static_cast<std::size_t>(x-min_x)] = ink;
 ++out.plotted;
 if (x == to.x && y == to.y) break;
 const int twice = 2*error;
 if (twice >= dy) { error += dy;
 x += sx;
 } if (twice <= dx) { error += dx;
 y += sy;
 } }
