BezierRaster raster_cubic_bezier(ControlPoint p0, ControlPoint p1, ControlPoint p2, ControlPoint p3, std::size_t sample_count) {
const ControlPoint points[4]={p0,p1,p2,p3};
if(sample_count<2||sample_count>129)return {};
for(auto p:points)if(!std::isfinite(p.x)||!std::isfinite(p.y)||p.x<-32||p.x>32||p.y<-32||p.y>32)return {};
BezierRaster out;
std::set<std::pair<int,int>> seen;

for(std::size_t i=0;i<sample_count;++i){const double t=static_cast<double>(i)/static_cast<double>(sample_count-1),u=1.0-t;
const double x=u*u*u*p0.x+3*u*u*t*p1.x+3*u*t*t*p2.x+t*t*t*p3.x;
const double y=u*u*u*p0.y+3*u*u*t*p1.y+3*u*t*t*p2.y+t*t*t*p3.y;
std::pair<int,int> point{static_cast<int>(std::lround(x)),static_cast<int>(std::lround(y))};
if(seen.insert(point).second)out.samples.push_back(point);
}int min_x=out.samples[0].first,max_x=min_x,min_y=out.samples[0].second,max_y=min_y;
for(auto point:out.samples){min_x=std::min(min_x,point.first);
max_x=std::max(max_x,point.first);
min_y=std::min(min_y,point.second);
max_y=std::max(max_y,point.second);
}out.rows.assign(static_cast<std::size_t>(max_y-min_y+1),std::string(static_cast<std::size_t>(max_x-min_x+1),'.'));
for(auto point:out.samples)out.rows[static_cast<std::size_t>(point.second-min_y)][static_cast<std::size_t>(point.first-min_x)]='#';
out.valid=true;
return out;

}
}
