MarqueeFrame clip_dot_matrix_marquee(const std::map<char, std::vector<std::string>>& glyphs, const std::string& message, std::size_t viewport_width, int offset) {
if(glyphs.empty()||message.empty()||viewport_width==0||viewport_width>80)return {};
std::size_t height=0;
for(const auto& item:glyphs){if(item.first<'!'||item.first>'~'||item.second.empty()||item.second.front().empty())return {};
if(height==0)height=item.second.size();
if(item.second.size()!=height)return {};
