for(const auto& row:item.second){if(row.size()!=width)return {};
for(char ch:row)if(ch!='.'&&ch!='#')return {};
}}std::vector<std::string> source(height);
for(std::size_t i=0;i<message.size();++i){auto found=glyphs.find(message[i]);
if(found==glyphs.end())return {};
if(i!=0)for(auto& row:source)row.push_back('.');
for(std::size_t r=0;r<height;++r)source[r]+=found->second[r];
}MarqueeFrame out;
out.valid=true;
