for(std::size_t r=0;r<height;++r)for(std::size_t c=0;c<viewport_width;++c){const long x=static_cast<long>(offset)+static_cast<long>(c);
if(x>=0&&x<static_cast<long>(out.source_width)){out.rows[r][c]=source[r][static_cast<std::size_t>(x)];
out.visible_ink+=out.rows[r][c]=='#';
}}return out;

}
