RuleTape evolve_elementary_rule(const std::string& seed, unsigned rule, std::size_t generation_count) {
if (seed.empty() || rule > 255 || generation_count == 0 || generation_count > 32) return {};
 for (char ch : seed) if (ch != '.' && ch != '#') return {};

RuleTape out;
 out.valid = true;
 std::string row = seed;

for (std::size_t generation = 0; generation < generation_count; ++generation) {
  out.generations.push_back(row);
 out.live_cells += static_cast<std::size_t>(std::count(row.begin(), row.end(), '#'));

  std::string next(row.size(), '.');
 for (std::size_t col = 0; col < row.size(); ++col) { unsigned index = 0;
 if (col > 0 && row[col - 1] == '#') index |= 4U;
 if (row[col] == '#') index |= 2U;
 if (col + 1 < row.size() && row[col + 1] == '#') index |= 1U;
 if (((rule >> index) & 1U) != 0U) next[col] = '#';
 } row = next;

}
return out;

}
