TurtlePlot plot_l_system(const std::string& axiom, const std::map<char, std::string>& productions, unsigned rounds) {
auto valid_symbol=[](char symbol){return (symbol>='A'&&symbol<='Z')||symbol=='+'||symbol=='-'||symbol=='['||symbol==']';
};
auto valid_stream=[&](const std::string& value){return std::all_of(value.begin(),value.end(),valid_symbol);
};
bool grammar_valid=!axiom.empty()&&rounds<=4&&axiom.size()<=4096&&valid_stream(axiom);
for(const auto& production:productions)grammar_valid=grammar_valid&&production.first>='A'&&production.first<='Z'&&valid_stream(production.second);
if(!grammar_valid)return {};
std::string stream = axiom;

for (unsigned round = 0; round < rounds; ++round) { std::string next;
 for (char symbol : stream) { auto found = productions.find(symbol);
 if (found == productions.end()) next.push_back(symbol);
 else { if(found->second.size()>4096-next.size())return {};
 next += found->second;
 } if (next.size() > 4096) return {};
 } stream = next;
 }
int row = 0, col = 0, direction = 0;
 const int dr[4] = {0, 1, 0, -1};
 const int dc[4] = {1, 0, -1, 0};
 std::vector<std::tuple<int,int,int>> stack;
 std::set<std::pair<int,int>> marks{{0,0}};

TurtlePlot out;
 for (char command : stream) { if (command == 'F') { row += dr[direction];
 col += dc[direction];
 marks.insert({row,col});
 ++out.forward_steps;
 } else if (command == '+') direction = (direction + 1) % 4;
 else if (command == '-') direction = (direction + 3) % 4;
 else if (command == '[') stack.push_back({row,col,direction});
 else if (command == ']') { if (stack.empty()) return {};
 std::tie(row,col,direction) = stack.back();
 stack.pop_back();
 } else if (command < 'A' || command > 'Z') return {};
 } if (!stack.empty()) return {};

int min_r = marks.begin()->first, max_r = min_r, min_c = marks.begin()->second, max_c = min_c;
 for (auto point : marks) { min_r = std::min(min_r, point.first);
 max_r = std::max(max_r, point.first);
 min_c = std::min(min_c, point.second);
 max_c = std::max(max_c, point.second);
 }
out.rows.assign(static_cast<std::size_t>(max_r-min_r+1), std::string(static_cast<std::size_t>(max_c-min_c+1), '.'));
 for (auto point : marks) out.rows[static_cast<std::size_t>(point.first-min_r)][static_cast<std::size_t>(point.second-min_c)] = '#';
 out.expanded_symbols = stream.size();
 out.valid = true;
 return out;

}
}
