NonogramGutters build_nonogram_gutters(const std::vector<std::string>& pixels) {
if(pixels.empty()||pixels.front().empty())return {};
const std::size_t cols=pixels.front().size();
for(const auto& row:pixels){if(row.size()!=cols)return {};
for(char ch:row)if(ch!='.'&&ch!='#')return {};
}NonogramGutters out;
out.valid=true;

auto clue=[](const std::string& line,std::size_t& run_count){std::string result;
std::size_t run=0;
for(std::size_t i=0;i<=line.size();++i){if(i<line.size()&&line[i]=='#'){++run;
}else if(run!=0){if(!result.empty())result.push_back(',');
result+=std::to_string(run);
++run_count;
run=0;
}}if(result.empty())result="0";
return result;
};

for(const auto& row:pixels){std::size_t count=0;
out.row_clues.push_back(clue(row,count));
out.max_row_runs=std::max(out.max_row_runs,count);
}for(std::size_t c=0;c<cols;++c){std::string column;
for(const auto& row:pixels)column.push_back(row[c]);
std::size_t count=0;
out.column_clues.push_back(clue(column,count));
out.max_column_runs=std::max(out.max_column_runs,count);
}return out;

}
