PolygonRaster fill_polygon_scanlines(const std::vector<Vertex>& vertices, char ink) {
if(vertices.size()<3||ink<'!'||ink>'~') return {};
 for(std::size_t i=0;i<vertices.size();++i){const auto& a=vertices[i];
const auto& b=vertices[(i+1)%vertices.size()];
if(a.x<-32||a.x>32||a.y<-32||a.y>32||(a.x==b.x&&a.y==b.y))return {};
}auto cross=[](Vertex a,Vertex b,Vertex c){return static_cast<long long>(b.x-a.x)*(c.y-a.y)-static_cast<long long>(b.y-a.y)*(c.x-a.x);
};
auto on_segment=[&](Vertex a,Vertex b,Vertex p){return cross(a,b,p)==0&&p.x>=std::min(a.x,b.x)&&p.x<=std::max(a.x,b.x)&&p.y>=std::min(a.y,b.y)&&p.y<=std::max(a.y,b.y);
};
auto intersects=[&](Vertex a,Vertex b,Vertex c,Vertex d){const long long ab_c=cross(a,b,c),ab_d=cross(a,b,d),cd_a=cross(c,d,a),cd_b=cross(c,d,b);
if(((ab_c>0&&ab_d<0)||(ab_c<0&&ab_d>0))&&((cd_a>0&&cd_b<0)||(cd_a<0&&cd_b>0)))return true;
return on_segment(a,b,c)||on_segment(a,b,d)||on_segment(c,d,a)||on_segment(c,d,b);
};
for(std::size_t i=0;i<vertices.size();++i){const Vertex previous=vertices[(i+vertices.size()-1)%vertices.size()],current=vertices[i],next=vertices[(i+1)%vertices.size()];
if(cross(previous,current,next)==0){const long long first_x=current.x-previous.x,first_y=current.y-previous.y,second_x=next.x-current.x,second_y=next.y-current.y;
if(first_x*second_x+first_y*second_y<0)return {};
}}for(std::size_t i=0;i<vertices.size();++i)for(std::size_t j=i+1;j<vertices.size();++j){if(j==i+1||(i==0&&j+1==vertices.size()))continue;
const Vertex a=vertices[i],b=vertices[(i+1)%vertices.size()],c=vertices[j],d=vertices[(j+1)%vertices.size()];
if(intersects(a,b,c,d))return {};
} int min_x=vertices[0].x,max_x=min_x,min_y=vertices[0].y,max_y=min_y;
for(auto v:vertices){min_x=std::min(min_x,v.x);
max_x=std::max(max_x,v.x);
min_y=std::min(min_y,v.y);
max_y=std::max(max_y,v.y);
}if(min_x==max_x||min_y==max_y)return {};

PolygonRaster out;
out.valid=true;
out.origin={min_x,min_y};
out.rows.assign(static_cast<std::size_t>(max_y-min_y),std::string(static_cast<std::size_t>(max_x-min_x),'.'));

for(int y=min_y;y<max_y;++y){const double scan=static_cast<double>(y)+0.5;
std::vector<double> crossings;
for(std::size_t i=0;i<vertices.size();++i){const auto a=vertices[i],b=vertices[(i+1)%vertices.size()];
if((static_cast<double>(a.y)<=scan&&scan<static_cast<double>(b.y))||(static_cast<double>(b.y)<=scan&&scan<static_cast<double>(a.y))){crossings.push_back(static_cast<double>(a.x)+(scan-a.y)*static_cast<double>(b.x-a.x)/static_cast<double>(b.y-a.y));
}}std::sort(crossings.begin(),crossings.end());
if(crossings.size()%2!=0)return {};
for(std::size_t pair=0;pair<crossings.size();pair+=2)for(int x=min_x;x<max_x;++x){const double center=static_cast<double>(x)+0.5;
if(center>=crossings[pair]&&center<crossings[pair+1]){out.rows[static_cast<std::size_t>(y-min_y)][static_cast<std::size_t>(x-min_x)]=ink;
++out.filled;
}}}
return out;

}
}
