CarpetStencil cut_sierpinski_carpet(unsigned order, char ink, char void_cell) {
if (order > 4 || ink < '!' || ink > '~' || void_cell < '!' || void_cell > '~' || ink == void_cell) return {};

std::size_t side = 1;
 for (unsigned i = 0; i < order; ++i) side *= 3;

CarpetStencil out;
 out.valid = true;
 out.rows.assign(side, std::string(side, ink));

for (std::size_t row = 0; row < side; ++row) for (std::size_t col = 0; col < side; ++col) {
  std::size_t rr = row, cc = col;
 bool removed = false;

  while (rr != 0 || cc != 0) { if (rr % 3 == 1 && cc % 3 == 1) { removed = true;
 break;
 } rr /= 3;
 cc /= 3;
 }
  if (removed) out.rows[row][col] = void_cell;
 else ++out.ink_cells;

}
return out;

}
