PrinterPage print_overstrike_stream(std::size_t rows, std::size_t cols, const std::string& stream) {
if(rows==0||cols==0||rows>32||cols>32||stream.empty())return {};
PrinterPage out;
out.rows.assign(rows,std::string(cols,' '));

for(unsigned char byte:stream){if(byte=='\b'){if(out.cursor_col==0)return {};
--out.cursor_col;
}else if(byte=='\r'){out.cursor_col=0;
}else if(byte=='\n'){if(out.cursor_row+1>=rows)return {};
++out.cursor_row;
}else if(byte>=32&&byte<=126){if(out.cursor_col>=cols)return {};
char& cell=out.rows[out.cursor_row][out.cursor_col];
if(cell!=' ')++out.overwritten;
cell=static_cast<char>(byte);
++out.cursor_col;
}else return {};
}
out.valid=true;
return out;

}
