#include "vertical-seam-carve.h"
#include <algorithm>
#include <cmath>
#include <limits>
#include <map>
#include <set>
#include <string>
#include <tuple>
#include <utility>
#include <vector>
namespace curriculum {
SeamCarve carve_vertical_seam(const std::vector<std::string>& pixels, const std::vector<std::vector<unsigned>>& energy) {
if(pixels.empty()||pixels.front().size()<2||energy.size()!=pixels.size())return {};
const std::size_t rows=pixels.size(),cols=pixels.front().size();
for(std::size_t r=0;r<rows;++r){if(pixels[r].size()!=cols||energy[r].size()!=cols)return {};
for(unsigned char ch:pixels[r])if(ch<32||ch>126)return {};
for(unsigned value:energy[r])if(value>100000)return {};
}std::vector<std::vector<unsigned long long>> cost(rows,std::vector<unsigned long long>(cols));
std::vector<std::vector<std::size_t>> parent(rows,std::vector<std::size_t>(cols));
for(std::size_t c=0;c<cols;++c)cost[0][c]=energy[0][c];

for(std::size_t r=1;r<rows;++r)for(std::size_t c=0;c<cols;++c){std::size_t best=c;
for(std::size_t p=(c==0?0:c-1);p<=std::min(cols-1,c+1);++p)if(cost[r-1][p]<cost[r-1][best]||(cost[r-1][p]==cost[r-1][best]&&p<best))best=p;
parent[r][c]=best;
cost[r][c]=cost[r-1][best]+energy[r][c];
}
std::size_t end=0;
for(std::size_t c=1;c<cols;++c)if(cost.back()[c]<cost.back()[end])end=c;
if(cost.back()[end]>std::numeric_limits<unsigned>::max())return {};
SeamCarve out;
out.valid=true;
out.total_energy=static_cast<unsigned>(cost.back()[end]);
out.seam_columns.assign(rows,0);
for(std::size_t r=rows;r-- >0;){out.seam_columns[r]=end;
if(r!=0)end=parent[r][end];
}for(std::size_t r=0;r<rows;++r){std::string row=pixels[r];
row.erase(row.begin()+static_cast<std::ptrdiff_t>(out.seam_columns[r]));
out.rows.push_back(row);
}return out;

}
}
