```
#include "alternating-parity-route.h"
#include <algorithm>
#include <array>
#include <cctype>
#include <cmath>
#include <deque>
#include <map>
#include <numeric>
#include <queue>
#include <set>
#include <utility>
namespace regions_mazes {
std::optional<std::vector<int>> alternating_parity_route(const GridRequest& request){
  const auto& g=request.grid;if(g.empty()||g.size()>32U||g.front().empty()||g.front().size()>32U)return std::nullopt;
  const int h=static_cast<int>(g.size()),w=static_cast<int>(g.front().size());
  const std::string allowed="#.SG";for(const auto& row:g)if(static_cast<int>(row.size())!=w||row.find_first_not_of(allowed)!=std::string::npos)return std::nullopt;
  int start=-1,goal=-1;for(int cell=0;cell<h*w;++cell){if(g[cell/w][cell%w]=='S'){if(start>=0)return std::nullopt;start=cell;}if(g[cell/w][cell%w]=='G'){if(goal>=0)return std::nullopt;goal=cell;}}if(start<0||goal<0)return std::nullopt;
  [[maybe_unused]] const std::array<std::pair<int,int>,4> dirs{std::pair<int,int>{-1,0},std::pair<int,int>{0,-1},std::pair<int,int>{0,1},std::pair<int,int>{1,0}};
  [[maybe_unused]] auto inside=[&](int r,int c){return r>=0&&r<h&&c>=0&&c<w;};
  std::vector<int> out;std::queue<std::array<int,3>> q;std::set<std::pair<int,int>> seen;for(int axis=0;axis<2;++axis){q.push({start,axis,0});seen.insert({start,axis});}while(!q.empty()){auto state=q.front();q.pop();int cell=state[0],prior=state[1],steps=state[2];if(cell==goal){out.push_back(steps);break;}for(auto [dr,dc]:dirs){int nr=cell/w+dr,nc=cell%w+dc,next=nr*w+nc,axis=dr!=0;if(inside(nr,nc)&&g[nr][nc]!='#'&&axis!=prior&&seen.insert({next,axis}).second)q.push({next,axis,steps+1});}}
  return out;
}
}
