  const int h=static_cast<int>(g.size()),w=static_cast<int>(g.front().size());
  const std::string allowed="#.SG";for(const auto& row:g)if(static_cast<int>(row.size())!=w||row.find_first_not_of(allowed)!=std::string::npos)return std::nullopt;
