p<out.vertex_offsets[static_cast<std::size_t>(vertex+1)];
++p){int neighbor=(p==out.vertex_offsets[static_cast<std::size_t>(vertex)])?out.neighbor_gaps[static_cast<std::size_t>(p)]:prior+out.neighbor_gaps[static_cast<std::size_t>(p)];
if(vertex<neighbor){out.decoded_edges.push_back(vertex);
out.decoded_edges.push_back(neighbor);
}prior=neighbor;
}}
out.directed_entry_count=static_cast<int>(out.neighbor_gaps.size());

  out.valid=true;return out;
}
bool validate_adjacency_gap_catalog_encoding(const AdjacencyGapCatalogRequest& request, const AdjacencyGapCatalogResult& encoded){
  if(!encoded.valid)return false;
