  const auto& values=request.edge_pairs;
  const int width=request.endpoint_width;
  const int parameter=request.vertex_count;
  (void)width;
  (void)parameter;

  if(width!=2||parameter<=0||values.size()%2U!=0U||result.vertex_offsets.size()!=static_cast<std::size_t>(parameter)+1U||result.vertex_offsets.front()!=0||result.vertex_offsets.back()!=static_cast<int>(result.neighbor_gaps.size())||result.directed_entry_count!=static_cast<int>(result.neighbor_gaps.size())||result.decoded_edges.size()%2U!=0U)return false;
std::set<std::pair<int,int>> expected;
for(std::size_t i=0;
i<values.size();
i+=2U){int a=values[i],b=values[i+1U];
if(a<0||b<0||a>=parameter||b>=parameter||a==b)return false;
auto edge=std::minmax(a,b);
if(!expected.insert(edge).second)return false;
}std::set<std::pair<int,int>> decoded;
