p<end;
++p){const int neighbor=p==begin?result.neighbor_gaps[static_cast<std::size_t>(p)]:prior+result.neighbor_gaps[static_cast<std::size_t>(p)];
if(neighbor<0||neighbor>=parameter||neighbor==vertex||neighbor<=prior)return false;
