FrontCodedPathLexiconResult front_coded_path_lexicon(const FrontCodedPathLexiconRequest& request){
  FrontCodedPathLexiconResult out;
  if(request.anchor_stride<=0)return {};
  for(std::size_t i=0;i<request.ordered_paths.size();++i){
    if(i>0&&request.ordered_paths[i]<=request.ordered_paths[i-1])return {};
    const std::string& prior=i==0?std::string():request.ordered_paths[i-1];
    std::size_t prefix=0;
    while(prefix<prior.size()&&prefix<request.ordered_paths[i].size()&&prior[prefix]==request.ordered_paths[i][prefix])++prefix;
    out.common_prefix_lengths.push_back(static_cast<int>(prefix));
    out.suffixes.push_back(request.ordered_paths[i].substr(prefix));
    if(i%static_cast<std::size_t>(request.anchor_stride)==0)out.anchors.push_back(request.ordered_paths[i]);
  }
  std::string prior;
  for(std::size_t i=0;i<out.suffixes.size();++i){
    const int prefix=out.common_prefix_lengths[i];
    if(prefix<0||static_cast<std::size_t>(prefix)>prior.size())return {};
    std::string decoded=prior.substr(0,static_cast<std::size_t>(prefix))+out.suffixes[i];
    if(i>0&&decoded<=prior)return {};
    out.decoded_paths.push_back(decoded);prior=std::move(decoded);
  }
  out.anchor_count=static_cast<int>(out.anchors.size());
  out.valid=true;return out;
}
bool validate_front_coded_path_lexicon_encoding(const FrontCodedPathLexiconRequest& request, const FrontCodedPathLexiconResult& encoded){
  if(!encoded.valid)return false;
  const auto& result=encoded;
  const auto& values=request.ordered_paths;
  const int width=request.anchor_stride;
  (void)width;

  if(width<=0||result.common_prefix_lengths.size()!=values.size()||result.suffixes.size()!=values.size()||result.decoded_paths!=values)return false;
std::vector<std::string> anchors;
std::string prior;
for(std::size_t i=0;
i<values.size();
++i){if(i>0&&values[i]<=values[i-1U])return false;
std::size_t prefix=0;
while(prefix<prior.size()&&prefix<values[i].size()&&prior[prefix]==values[i][prefix])++prefix;
if(result.common_prefix_lengths[i]!=static_cast<int>(prefix)||result.suffixes[i]!=values[i].substr(prefix))return false;
if(i%static_cast<std::size_t>(width)==0U)anchors.push_back(values[i]);
prior=values[i];
}
return result.anchors==anchors&&result.anchor_count==static_cast<int>(anchors.size());

}
