  FullOuterMergeTableResult out;(void)width;(void)parameter;if(width<=0)return out;
  if(parameter<0||static_cast<std::size_t>(parameter)>values.size())return FullOuterMergeTableResult{};
for(int p=1;
p<parameter;
++p)if(values[static_cast<std::size_t>(p)]<=values[static_cast<std::size_t>(p-1)])return FullOuterMergeTableResult{};
for(std::size_t p=static_cast<std::size_t>(parameter)+1U;
p<values.size();
++p)if(values[p]<=values[p-1U])return FullOuterMergeTableResult{};
std::size_t i=0,j=static_cast<std::size_t>(parameter);
while(i<static_cast<std::size_t>(parameter)||j<values.size()){int key;
