out.presence_masks.push_back(2);
}else{key=values[i];
++i;
++j;
out.presence_masks.push_back(3);
}
out.merged_keys.push_back(key);
}std::vector<int> left,right;
for(std::size_t i=0;
i<out.merged_keys.size();
++i){if(out.presence_masks[i]&1)left.push_back(out.merged_keys[i]);
if(out.presence_masks[i]&2)right.push_back(out.merged_keys[i]);
}
out.decoded_inputs=left;
out.decoded_inputs.insert(out.decoded_inputs.end(),right.begin(),right.end());
out.merged_count=static_cast<int>(out.merged_keys.size());

  out.valid=true;return out;
}
