  const int width=request.key_hint;
  const int parameter=request.left_count;
  (void)width;
  (void)parameter;

  if(parameter<0||static_cast<std::size_t>(parameter)>values.size()||result.merged_keys.size()!=result.presence_masks.size()||result.decoded_inputs!=values||result.merged_count!=static_cast<int>(result.merged_keys.size()))return false;
for(int i=1;
i<parameter;
++i)if(values[static_cast<std::size_t>(i)]<=values[static_cast<std::size_t>(i-1)])return false;
for(std::size_t i=static_cast<std::size_t>(parameter)+1U;
i<values.size();
++i)if(values[i]<=values[i-1U])return false;
std::vector<int> left,right;
for(std::size_t i=0;
i<result.merged_keys.size();
++i){if(i>0&&result.merged_keys[i]<=result.merged_keys[i-1U])return false;
const int mask=result.presence_masks[i];
if(mask<1||mask>3)return false;
if((mask&1)!=0)left.push_back(result.merged_keys[i]);
