  const auto& result=encoded;
  const auto& values=request.rows;
  const std::size_t width=request.maximum_row_length;
  (void)width;

  if(width==0U||result.row_offsets.size()!=values.size()+1U||result.row_offsets.empty()||result.row_offsets.front()!=0||result.row_offsets.back()!=static_cast<int>(result.payload.size())||result.decoded_rows!=values||result.row_count!=static_cast<int>(values.size()))return false;
std::size_t cursor=0;
for(std::size_t row=0;
row<values.size();
++row){if(values[row].size()>width||result.row_offsets[row]!=static_cast<int>(cursor))return false;
for(int value:values[row]){if(cursor>=result.payload.size()||result.payload[cursor++]!=value)return false;
}
if(result.row_offsets[row+1U]!=static_cast<int>(cursor))return false;
}
return cursor==result.payload.size();

}
}
