  if(!encoded.valid)return false;
  const auto& result=encoded;
  const auto& values=request.update_triples;
  const int width=request.coordinate_limit;
  const int parameter=request.default_value;
  (void)width;
  (void)parameter;

  if(width<=0||values.size()%3U!=0U||result.decoded_overlay.size()!=static_cast<std::size_t>(width)||result.overlay_pairs.size()%2U!=0U||result.sequence_metadata.size()%2U!=0U||result.coordinate_count!=static_cast<int>(result.overlay_pairs.size()/2U))return false;
std::map<int,std::pair<int,int>> latest;
std::map<int,std::set<int>> seen;
for(std::size_t i=0;
i<values.size();
i+=3U){const int coordinate=values[i],sequence=values[i+1U],value=values[i+2U];
if(coordinate<0||coordinate>=width||!seen[coordinate].insert(sequence).second)return false;
auto found=latest.find(coordinate);
if(found==latest.end()||sequence>found->second.first)latest[coordinate]={sequence,value};
}std::vector<int> overlay,metadata,decoded(static_cast<std::size_t>(width),parameter);
for(const auto& [coordinate,winner]:latest){metadata.insert(metadata.end(),{coordinate,winner.first});
if(winner.second!=parameter){overlay.insert(overlay.end(),{coordinate,winner.second});
decoded[static_cast<std::size_t>(coordinate)]=winner.second;
}}
