if(result.validity_words.size()!=words)return false;
for(std::size_t i=0;
i<rows;
++i){if(request.ids[i]<0||!ids.insert(request.ids[i]).second||request.value_validity[i]<0||request.value_validity[i]>1)return false;
const bool present=((result.validity_words[i/30U]>>static_cast<int>(i%30U))&1)!=0;
if(present!=(request.value_validity[i]!=0)||result.value_column[i]!=(present?request.values[i]:0)||result.decoded_records[2U*i]!=request.ids[i]||result.decoded_records[2U*i+1U]!=result.value_column[i])return false;
}
