namespace{struct V{int x,y,z;};V neg(V a){return {-a.x,-a.y,-a.z};}bool eq(V a,V b){return a.x==b.x&&a.y==b.y&&a.z==b.z;}bool valid(Face f){return f==Face::front||f==Face::right||f==Face::back||f==Face::left||f==Face::top||f==Face::bottom;}bool valid(Heading h){return h==Heading::east||h==Heading::south||h==Heading::west||h==Heading::north;}struct B{V n,u,v;};B basis(Face f){switch(f){case Face::front:return {{0,0,1},{1,0,0},{0,1,0}};case Face::right:return {{1,0,0},{0,0,-1},{0,1,0}};case Face::back:return {{0,0,-1},{-1,0,0},{0,1,0}};case Face::left:return {{-1,0,0},{0,0,1},{0,1,0}};case Face::top:return {{0,-1,0},{1,0,0},{0,0,1}};case Face::bottom:return {{0,1,0},{1,0,0},{0,0,-1}};}return {};}Face face_for(V n){for(Face f:{Face::front,Face::right,Face::back,Face::left,Face::top,Face::bottom})if(eq(basis(f).n,n))return f;return Face::front;}} std::optional<FaceCell> step_cube(FaceCell c,int size){if(!valid(c.face)||!valid(c.heading)||size<=0||c.row<0||c.column<0||c.row>=size||c.column>=size)return std::nullopt;int dr=0,dc=0;switch(c.heading){case Heading::east:dc=1;break;case Heading::south:dr=1;break;case Heading::west:dc=-1;break;case Heading::north:dr=-1;break;}int nr=c.row+dr,nc=c.column+dc;if(nr>=0&&nr<size&&nc>=0&&nc<size)return FaceCell{c.face,nr,nc,c.heading};B old=basis(c.face);V move=dc==1?old.u:dc==-1?neg(old.u):dr==1?old.v:neg(old.v);Face nf=face_for(move);B nb=basis(nf);V forward=neg(old.n);Heading h=Heading::east;if(eq(forward,nb.v))h=Heading::south;else if(eq(forward,neg(nb.u)))h=Heading::west;else if(eq(forward,neg(nb.v)))h=Heading::north;int offset=(dc!=0)?c.row:c.column;int rr=0,cc=0;if(h==Heading::east){rr=offset;cc=0;}else if(h==Heading::west){rr=offset;cc=size-1;}else if(h==Heading::south){rr=0;cc=offset;}else{rr=size-1;cc=offset;}return FaceCell{nf,rr,cc,h};}
