namespace{std::optional<std::vector<std::uint64_t>> strides(const std::vector<std::uint32_t>&s,const std::vector<unsigned>&o,std::uint64_t&cap){if(s.empty()||s.size()!=o.size())return std::nullopt;std::vector<bool>seen(s.size());std::vector<std::uint64_t>st(s.size());cap=1;for(unsigned axis:o){if(axis>=s.size()||seen[axis]||s[axis]==0)return std::nullopt;seen[axis]=true;st[axis]=cap;if(cap>std::numeric_limits<std::uint64_t>::max()/s[axis])return std::nullopt;cap*=s[axis];}return st;}} std::optional<std::uint64_t> tensor_linearize(const std::vector<std::uint32_t>&s,const std::vector<unsigned>&o,const std::vector<std::uint32_t>&c){std::uint64_t cap=0;auto st=strides(s,o,cap);if(!st||c.size()!=s.size())return std::nullopt;std::uint64_t out=0;for(std::size_t i=0;i<s.size();++i){if(c[i]>=s[i])return std::nullopt;out+=std::uint64_t(c[i])*(*st)[i];}return out;} std::optional<std::vector<std::uint32_t>> tensor_unlinearize(const std::vector<std::uint32_t>&s,const std::vector<unsigned>&o,std::uint64_t index){std::uint64_t cap=0;auto st=strides(s,o,cap);if(!st||index>=cap)return std::nullopt;std::vector<std::uint32_t>c(s.size());for(auto it=o.rbegin();it!=o.rend();++it){unsigned a=*it;c[a]=std::uint32_t(index/(*st)[a]);index%=(*st)[a];}return c;}
