}
}
SerialScheduleTotal::Report SerialScheduleTotal::analyze(const std::vector<Entry>& entries, long long limit) const {
  Report report{true, 0, -1, 0, 0, {}};
  if (limit < 0) return {false, 0, -1, 0, 0, {}};
  std::set<std::string> ids;
  std::vector<Entry> ordered;
  for (const auto& entry : entries) {
    if (entry.id.empty() || entry.start < 0 || entry.end < entry.start ||
        entry.amount < 0 || entry.sequence < 0 || !ids.insert(entry.id).second) {
      ++report.rejected;
      continue;
    }
    ordered.push_back(entry);
  }
  std::stable_sort(ordered.begin(), ordered.end(), [](const Entry& left, const Entry& right) {
    return left.sequence != right.sequence ? left.sequence < right.sequence : left.start != right.start ? left.start < right.start : left.id < right.id;
  });
  if (ordered.size() > static_cast<std::size_t>(INT_MAX)) return {false, 0, -1, 0, 0, {}};
  report.accepted = static_cast<int>(ordered.size());
  Big accumulator = 0;
  Big witness = -1;
  bool arithmetic_ok = true;
  Big serial_cursor = 0;
  const auto checked_add = [&arithmetic_ok](Big& target, const Big& increment) {
  Big result = 0;
  if (__builtin_add_overflow(target, increment, &result)) arithmetic_ok = false;
  else target = result;
};
  std::size_t index = 0;
  for (const auto& entry : ordered) {
    const Big span = Big(entry.end) - Big(entry.start);
    serial_cursor = serial_cursor > Big(entry.start) ? serial_cursor : Big(entry.start);
    checked_add(serial_cursor, span);
    checked_add(serial_cursor, Big(entry.amount));
    Big sample = serial_cursor;
    checked_add(accumulator, sample);
    ++index;
  }

  if (!arithmetic_ok || !fits_long_long(accumulator) || !fits_long_long(witness)) {
    return {false, 0, -1, 0, 0, {}};
  }
  report.value = static_cast<long long>(accumulator);
  report.witness = static_cast<long long>(witness);
  for (const auto& entry : ordered) report.events.push_back(entry.id);
  return report;
}
}
